'use strict';
(globalThis.ABBATE_QUESTION_TRANSLATIONS||(globalThis.ABBATE_QUESTION_TRANSLATIONS={}))["nl"]={"g-flurpruefung":["Wat houdt een visuele en functionele inspectie vóór aanvang van de werkzaamheden in?","Vóór de eerste missie van de dag.","Controleer alleen het brandstofniveau en de kleur van het voertuig.","Controleer remmen, stuurinrichting, vorken, banden en veiligheidsvoorzieningen volgens de gebruiksaanwijzing.","Voer een proefrit uit met geheven last.","De dagelijkse inspectie omvat de veiligheidsrelevante onderdelen en functies volgens de bedieningshandleiding."],"g-rueckhalt":["Hoe gaat u om met het bestaande beveiligingssysteem voor de bestuurder?","De vorkheftruck is voorzien van een verplicht bevestigingssysteem.","Gebruik het op de juiste manier tijdens het rijden.","Alleen gebruiken op oneffen vloeren.","Voor korte ritten deactiveer je hem.","De beoogde bevestigingssystemen moeten worden gebruikt in overeenstemming met de instructies van de fabrikant; ze bieden bijzondere bescherming bij kantelgebeurtenissen."],"g-mangelmelden":["Wat geldt voor een heftruck met een beschadigde vork?","Bij het controleren valt een duidelijk verbogen tand op.","Verdeel indien mogelijk de belasting over de andere tand.","Rijd slechts met lichte lasten tot de volgende onderhoudsbeurt.","Gebruik de heftruck niet en meld het defect aan de verantwoordelijke persoon.","Beschadigde lastopnamemiddelen kunnen defect raken; Veiligheidsgerelateerde defecten vereisen uitschakeling tot opheldering."],"g-einweisung":["Je stapt over naar een heftruck met verschillende bedieningen. Wat is er nodig vóór gebruik?","De bediening wijkt af van uw vorige voertuig.","Apparaatgerelateerde instructie en naleving van de bedieningshandleiding.","Een korte uitleg van een niet-betrokken collega is altijd voldoende.","Geen aanvullende informatie als je een heftruckcertificaat hebt.","Een algemene kwalificatie vervangt niet de noodzakelijke instructie op het daadwerkelijk gebruikte apparaat."],"g-anbaugeraet":["U dient een bijlage te gebruiken. Wat controleer je eerst?","Een nieuw apparaat verandert de manier waarop de lading wordt opgepakt.","Of het aanbouwapparaat past bij de voertuiggoedkeuring en de toegestane belasting.","Alleen of het apparaat visueel kan worden bevestigd.","Of het opzetstuk zonder documentatie kan worden geïnstalleerd.","Aanbouwdelen kunnen het resterende laadvermogen en het laadzwaartepunt wijzigen; Goedkeuringen en informatie over het draagvermogen moeten worden gecontroleerd."],"g-diagramm":["Waarom heb je het draagvermogendiagram nodig?","Er is sprake van een zware last met het zwaartepunt ver naar buiten.","Om de kortste route te bepalen.","Om de maximaal toegestane belasting te beoordelen, afhankelijk van de hefhoogte en het lastzwaartepunt.","Om de tankinhoud te bepalen.","Toegestane lasten zijn onder andere afhankelijk van de lastzwaartepuntafstand en de hefhoogte."],"g-lastschwerpunkt":["Wat gebeurt er doorgaans als het zwaartepunt verder naar voren beweegt?","Een lange last steekt ver voor de vorken uit.","Het toegestane draagvermogen kan afnemen.","Het draagvermogen neemt voortdurend toe.","De afstand heeft geen invloed op het kantelmoment.","Een grotere afstand tot het lastzwaartepunt vergroot het kipmoment en kan het toegestane laadvermogen verminderen."],"g-gabelabstand":["Hoe moeten de vorken een geschikte pallet oppakken?","U wilt een gelijkmatig beladen pallet oppakken.","Met de tanden zo dichtbij mogelijk en slechts op één hoek.","Met zo’n grote afstand dat de pallet opzij kantelt.","Met geschikte tandafstand en voldoende onderstel en steunvlak.","De lading moet veilig en zo gelijkmatig mogelijk over de vorken worden ondersteund."],"g-schieflast":["Een lading is instabiel gestapeld. Wat is juist?","Kartonnen dozen kunnen vallen als ze worden opgetild.","Begin langzaam; de lading stabiliseert zichzelf.","Voordat u de last oppakt, dient u deze voldoende vast te zetten of weer te laten monteren.","Hef de last boven hoofdhoogte, zodat deze niet in de weg zit.","Losse of onstabiele lading kan vallen en mensen in gevaar brengen; Voer eerst veiligheidsmaatregelen uit."],"g-personen":["Kan iemand op gewone vorken worden getild?","Een collega wil een licht bereiken.","Ja, als de collega een helm draagt.","Nee, alleen aangewezen en toegestane voorzieningen mogen door personen worden gebruikt in overeenstemming met bijzondere eisen.","Ja, als slechts een kleine hoogte wordt benaderd.","Normale vorken zijn geen persoonlijk werkplatform; Voor het vervoeren en tillen van personen gelden speciale eisen."],"g-transporthoehe":["Hoe transporteer jij normaal gesproken een pallet?","De weg is duidelijk en vlak.","Met de last alleen voor zover nodig geheven en in overeenstemming met de bedieningshandleiding.","Met de last zo hoog mogelijk geheven om beter gezien te worden.","Met de hefmast sterk naar voren gekanteld, ongeacht de last.","Een lage transportpositie vermindert de kans op kantelen en botsingen; De apparaatinstructies zijn doorslaggevend."],"g-kurvenfahrt":["Waarom is snel bochten nemen met een vorkheftruck gevaarlijk?","Je wilt snel een smal pad verlaten.","Omdat de batterij hierdoor gewoon sneller leeg raakt.","Omdat de heftruck automatisch beter stuurt.","Omdat zijdelingse krachten de stabiliteit beïnvloeden en tot kantelen kunnen leiden.","Bij het nemen van bochten spelen extra krachten een rol; de snelheid moet worden aangepast aan de belasting en omstandigheden."],"g-ladebruecke":["Wat controleer je voordat je een laadbrug oprijdt?","Je zou in een vrachtwagen moeten rijden.","Het is maar of het pad breed genoeg lijkt.","Laadvermogen, veilige ondersteuning en bescherming tegen verschuiven en beveiliging van het voertuig.","Het is maar of de verlichting aan is.","Laadbruggen en voertuigen moeten beveiligd zijn tegen beweging en geschikt zijn voor de lading."],"g-fussgaenger":["Hoe gedraag je je op een verwarrend kruispunt met voetgangers?","Visuele verbindingen zijn beperkt.","Rijd met de juiste snelheid, stop indien nodig en zorg voor veilig zicht.","Claim altijd voorrang als u een last vervoert.","Gewoon toeteren en blijven rijden.","Voetgangers hebben speciale beschermingsbehoeften; Snelheid, zichtbaarheid en communicatie moeten worden aangepast aan de verkeersroute."],"g-batterieladen":["Waar moet u vooral op letten bij het opladen van een rijaccu?","Er wordt gebruik gemaakt van een acculaadstation.","De oplaadlocatie kan worden geselecteerd ongeacht de instructies van de fabrikant.","Open vuur is toegestaan ​​zolang de vrachtwagen stilstaat.","Geschikte laadruimte, voldoende ventilatie en fabrieksspecificaties, evenals brand- en explosiebeveiliging.","Bij het opladen kunnen gevaren ontstaan ​​door elektrische energie, gassen en chemicaliën; de voorziene beschermingsmaatregelen moeten worden nageleefd."],"h-beauftragt":["Onder welke voorwaarden mag u zelfstandig een hoogwerker bedienen?","U dient binnen het bedrijf gebruik te maken van een werkplatform.","Als je een autorijbewijs hebt.","Als u geschikt, geïnstrueerd of gekwalificeerd bent en in opdracht van de werkgever.","Als je ooit een werkplatform hebt gezien.","De werkgever moet zorgen voor geschiktheid, kwalificaties en opdrachten in overeenstemming met de operationele vereisten."],"h-vorpruefung":["Wat moet er gecontroleerd worden voordat er met de hoogwerker gewerkt wordt?","Het podium stond 's nachts buiten.","Visuele en functionele test volgens de instructies van de fabrikant, inclusief veiligheidsvoorzieningen.","Alleen de kleur en leeftijd van het podium.","Of het werkmateriaal al op het platform staat.","Voor gebruik moeten de machine, besturingen, noodfuncties en zichtbare beschadigingen worden gecontroleerd volgens de bedieningshandleiding."],"h-tragfaehigkeit":["Welke informatie bepaalt de toegestane belasting van de werkbak?","Twee personen willen graag extra gereedschap meenemen.","Mensen zijn vrij om het toegestane totaalgewicht in te schatten.","Alleen het gewicht van de zwaarste persoon telt.","De draagvermogensspecificatie voor personen, gereedschap en materiaal mag niet worden overschreden.","De nominale belasting heeft betrekking op de totaal toegestane belasting, inclusief vervoerd materiaal."],"h-untergrund":["Waar let je op voordat je een podium met steunen opzet?","Je werkt in de buurt van een gevuld gebied.","Alleen binnen het bereik van de giek.","Controleer het draagvermogen en de vlakheid van de ondergrond en een geschikte ondergrond volgens de instructies.","Op een zo laag mogelijk aantal verlengde steunen.","Onvoldoende grond of onjuiste ondersteuning kan leiden tot verlies van stabiliteit."],"h-wind":["Er steekt een harde wind op. Hoe pak je dat aan?","Je beschikt over een buitenpodium.","Neem de limieten van de fabrikant in acht en als deze worden overschreden, stop dan met werken of laat de mand veilig zakken.","Verleng het platform zo ver mogelijk zodat het stabieler is.","Reageer alleen als er losse voorwerpen vallen.","De door de fabrikant toegestane windomstandigheden zijn gebruikslimieten; Wind kan gevaarlijke extra krachten veroorzaken."],"h-strom":["Je moet in de buurt van een bovengrondse hoogspanningslijn werken. Wat is cruciaal?","Er bevindt zich een stroomlijn in het werkgebied.","Een helm vervangt het bewaren van een veilige afstand.","Isoleer gewoon de mand en werk zonder coördinatie.","Maak de gevarenzone duidelijk en zorg voor de noodzakelijke veiligheidsafstanden of andere passende maatregelen.","Elektrische flashover is ook mogelijk zonder direct contact; De noodzakelijke beschermende maatregelen moeten vóór aanvang van de operatie worden bepaald."],"h-notablass":["Waarom moet de nooddaalprocedure bekend zijn?","Een uitval van de normale besturing is mogelijk.","Zodat bij een storing een veilige redding mogelijk is volgens het apparaat.","Zodat het apparaat bij normaal gebruik sneller werkt.","Ter vervanging van reguliere testen.","Noodbedieningen, nooddaal- en reddingsconcepten moeten vóór gebruik bekend en functioneel zijn."],"h-gelaender":["Hoe bereik je extra hoogte in de werkmand?","Een montagepunt ligt net buiten uw bereik.","Klim op het hek van de mand.","Plaats een plank op de reling.","Gebruik een geschikt platform met voldoende werkhoogte; klim niet op relingen.","Het beklimmen van het hekwerk of geïmproviseerde verhogingen brengen de valbeveiliging in gevaar."],"h-psaga":["Welke eisen gelden er voor persoonlijke valbeveiligingsmiddelen?","U maakt gebruik van een werkplatform waarvoor een vastzetsysteem is voorzien.","Elk ankerpunt buiten de mand is altijd voldoende.","Neem de risicobeoordeling, de informatie van de fabrikant en geschikte ankerpunten in acht.","Gebruik geen beveiliging als de mand een reling heeft.","Of en welke PBM’s nodig zijn, wordt bepaald door de risicobeoordeling, podiumopbouw en bedieningsinstructies."],"h-verfahren":["Kan het podium worden verplaatst als het platform omhoog staat?","De werkplek ligt op een paar meter afstand.","Alleen als het model en de bedrijfsomstandigheden dit toelaten volgens de instructies van de fabrikant.","Altijd, zolang iedereen volhoudt.","Nee, nooit ongeacht het ontwerp en de goedkeuring van de fabrikant.","De beweging in geheven positie is afhankelijk van het apparaat en is alleen toegestaan ​​binnen de goedgekeurde bedrijfsomstandigheden."],"h-kollision":["Wat moet er geregeld worden bij het werken in de buurt van kranen of andere machines?","Bewegende delen kunnen de werkbak bereiken.","Niets; de werkmand is altijd zichtbaar.","Rijd altijd met de werkbak over de andere machines.","Coördineer werkgebieden om botsingen of knelpunten te voorkomen.","Gelijktijdige machinebediening vereist gecoördineerde werkprocessen en bescherming tegen botsingen of vastlopen."],"h-einstieg":["Hoe kom je in of uit de werkmand?","Je bereikt de mand op grondniveau.","Klim over de buitenleuning.","Via de beoogde toegang in een veilige positie volgens de bedieningsinstructies.","Via een ernaast geplaatste ladder met uitgeschoven giek.","De beoogde toegang en de instructies van de fabrikant moeten worden nageleefd; Als u er ongecontroleerd overheen klimt, bestaat er een risico op vallen."],"h-defekt":["De noodstopvoorziening werkt niet. Wat ben je aan het doen?","Tijdens de inspectie ontdekt u het defect.","Gebruik het platform niet en meld het defect.","Ga door met werken als de normale bedieningselementen werken.","Plak de schakelaar vast, zodat niemand hem bedient.","Het uitvallen van een veiligheidsvoorziening is een veiligheidsrelevant defect en verhindert een veilige werking."],"h-sicht":["Door een obstakel is de rijbeweging niet zichtbaar. Hoe ga je ermee om?","Je moet een mobiel podium verplaatsen.","Rijd langzaam zonder zicht.","Vertrouw gewoon op de afstandsindicator.","Stop de beweging en zorg voor zichtbaarheid of veilige instructies volgens de bedieningsinstructies.","Vóór de procedure moeten mensen, obstakels en verkeersroutes veilig worden geïnspecteerd."],"h-rettung":["Wat houdt de inzetplanning in bij het werken op grotere hoogte?","Het podium wordt gebruikt in een afgelegen gebied.","Alleen de geplande werkduur.","Een passend reddingsconcept met toegankelijke, getrainde mensen en nooddaalprocedures.","De veronderstelling dat de brandweer ieder probleem direct oplost.","Een effectieve redding moet vooraf worden georganiseerd, zelfs als de normale controles falen."],"k-befaehigung":["Wat is er nodig om een ​​kraan zelfstandig te kunnen bedienen?","Het is de bedoeling dat een nieuwe medewerker het kraanwerk overneemt.","Geschiktheid en vereiste kwalificaties, instructie en bijbehorende opdracht.","Een autorijbewijs is voldoende.","Eén keer kijken is genoeg.","Kraanwerkzaamheden mogen uitsluitend worden toevertrouwd aan gekwalificeerde en bevoegde personen; Apparatuurinstructie is daar een onderdeel van."],"k-funktionspruefung":["Wat is er nodig om de kraan te controleren vóór aanvang van de dienst?","Je neemt een binnenkraan over.","Lees gewoon de looptijd op het typeplaatje.","Controleer veiligheidsrelevante functies en zichtbare gebreken volgens de bedieningshandleiding.","Test de kraan met maximale belasting zonder te controleren.","De verplichte operationele controle dient om gevaarlijke gebreken in een vroeg stadium te identificeren."],"k-traglast":["Wat is de betekenis van het toegestane draagvermogen?","Er moet een last worden gehesen.","Het is een niet-bindend advies.","Dit geldt alleen als de haak volledig is ingetrokken.","Het toegestane draagvermogen voor de betreffende bedrijfsomstandigheden mag niet worden overschreden.","Toegestane belastingen voor bepaalde typen kranen kunnen afhankelijk zijn van de radius, giekpositie en bewapening."],"k-personen":["Wat geldt voor mensen onder hangende lasten?","De last wordt over een werkgebied verplaatst.","De gevarenzone moet vrijgehouden worden; niemand mag onder de hangende last stappen.","Met een helm kun je er direct onder blijven.","Korte overtochten zijn toegestaan ​​als de kraan langzaam beweegt.","Hangende lasten vormen een risico op vallen en beknelling; Mensen moeten uit de gevarenzone worden gehouden."],"k-signale":["Je ziet de aanvaller niet en je krijgt tegenstrijdige signalen. Wat ben je aan het doen?","De communicatie is onduidelijk.","Ga door met het laatste rijcommando.","Stop de beweging en verduidelijk de communicatie duidelijk.","Zonder overleg sneller de lading neerzetten.","Veilige lastbewegingen vereisen duidelijke signalen en duidelijke communicatie."],"k-sicht":["Wie biedt ondersteuning tijdens het transport als de kraanmachinist het lastpad niet volledig kan overzien?","Een halpilaar verduistert het pad.","Een persoon die toevallig langskomt zonder voorafgaande toestemming.","Niemand; alleen de haak is belangrijk.","Een geschikte, geïnstrueerde persoon met duidelijk afgesproken begrip.","Als het lastpad niet zichtbaar is, is passende instructie of een andere veilige oplossing vereist."],"k-ruck":["Waarom moeten schokkerige kraanbewegingen worden vermeden?","Een zware last begint te zwaaien.","Ze creëren extra dynamische spanningen en kunnen de lading destabiliseren.","Ze verminderen in principe elke slingerbeweging.","Ze verhogen altijd het nominale draagvermogen.","Acceleratie- en remkrachten verhogen de belasting van de kraan en de stroppen."],"k-sperrbereich":["Wat moet u controleren voordat u een last in een gedeelde ruimte zwaait?","Andere medewerkers werken in de buurt.","Of de lading visueel aansluit bij de kraan.","Of de gevarenzone beveiligd is en er geen mensen in gevaar zijn.","Of de last zo hoog mogelijk boven iedereen gedragen kan worden.","De zwenk- en lastpaden moeten vrij zijn van onbeschermde personen."],"k-stuetzen":["Wat is cruciaal voor een mobiele kraan met stempels?","Op gedeeltelijk gevulde grond wordt een kraan opgesteld.","Gewoon de breedte van de weg.","De kleur van de steunplaten.","Dragende basis, steun en lastverdeling volgens montage- en fabrikantinstructies.","De installatie heeft een grote invloed op de stabiliteit, vooral bij veranderende bodemomstandigheden."],"k-wetter":["Een windvlaag zorgt ervoor dat de lading aanzienlijk gaat zwaaien. Wat is juist?","Je werkt buitenshuis.","Stop de beweging veilig en neem de toegestane bedrijfsomstandigheden in acht.","Versnel de beweging snel.","Ga door met het heffen van de last ondanks het overschrijden van de limieten van de fabrikant.","Wind- en slingerbewegingen kunnen de lading en kraan destabiliseren; De toepassingslimieten moeten in acht worden genomen."],"k-freileitung":["Wat is van toepassing bij het gebruik van kranen in de buurt van bovengrondse elektriciteitsleidingen?","De giek of last kan de lijn naderen.","Bij een niet-geleidende belasting zijn spelingen onbelangrijk.","Informeer vóór aanvang van de werkzaamheden samen met de verantwoordelijken de gevarenzone en de noodzakelijke beschermingsmaatregelen.","Vertrouw alleen op de eigen reactie van de kraanmachinist.","Er zijn gevaren door contact en spanningsoverslag; veilige beschermende afstanden of andere maatregelen zijn vereist."],"k-sichern":["Wat doe je voordat je de kraan verlaat?","Het werk wordt onderbroken.","Laat de last hangen.","Laat de kraan onbeheerd achter terwijl de aandrijving draait.","Laat de last veilig zakken en zet de kraan vast volgens de bedieningsinstructies.","Hangende lasten mogen niet ongecontroleerd worden achtergelaten; De kraan en de lading moeten veilig geparkeerd worden."],"k-lastanschlag":["Hoe weet je of de gebruikte tilband geschikt is?","De last moet worden gehesen met behulp van een hijsband.","Qua markering, draagvermogen, staat en geschiktheid voor het type aanbouwapparaat.","Alleen al door de kleur van de hijsband.","Omdat het gisteren al gebruikt werd.","Laadvermogen en -conditie moeten voldoende zijn, rekening houdend met de aanbouwvoorwaarden."],"k-stopp":["Een persoon betreedt onverwacht het laadpad. Wat ben je aan het doen?","De kraan verplaatst momenteel een last.","Stop de beweging onmiddellijk veilig en laat de gevarenzone ontruimen.","Geef gewoon een waarschuwingssignaal en blijf rijden.","Hef de last hoger en rijd eroverheen.","Mensen moeten worden beschermd tegen lastbewegingen; Als er direct gevaar dreigt, moet de beweging worden gestopt."],"k-neuerkran":["Je ontvangt een kraan met een onbekende besturing. Wat is juist?","De besturing is anders dan voorheen.","Probeer de gebruikelijke toetsen als u dit vermoedt.","Laat iemand anders zonder training voorrijden.","Ontvang de nodige apparaatgerelateerde instructies vóór zelfstandig gebruik.","Zelfs ervaren kraanmachinisten hebben kennis nodig van de specifieke gebruikte bedieningselementen, beveiligingsapparatuur en limieten."],"a-kennzeichnung":["Hoe weet je wat het toegestane draagvermogen van een tilband is?","Je wilt een draagdoek kiezen.","De geur van het materiaal.","Op de juiste, leesbare markering van het draagvermogen en informatie van de fabrikant.","Over de duur van de opslag.","Het toegestane draagvermogen wordt bepaald door de etikettering en de bedrijfsomstandigheden."],"a-sichtpruefung":["Je merkt een duidelijke snede in de hijsband. Hoe ga je ermee om?","De band moet een last dragen.","Gebruik de tape niet en stuur deze op voor testen of afkeuren.","Bedek de snede met tape.","Gebruik het alleen voor bijzonder lichte belasting.","Beschadigde textielstroppen kunnen defect raken en moeten worden beoordeeld aan de hand van de wegwerpcriteria."],"a-neigungswinkel":["Wat gebeurt er als de hellingshoek van de slingstrengen groter is dan de verticale?","Een hanger met twee strengen spreidt meer uit.","De strengkrachten nemen altijd af.","De strengkrachten blijven hetzelfde.","De krachten in de strengen nemen toe; Toegestane hoeken en draagvermogens moeten in acht worden genomen.","Naarmate de spreiding toeneemt, neemt de trekkracht per steunstreng toe."],"a-schwerpunkt":["Waarom moet u het zwaartepunt van de lading weten?","De belasting is ongelijkmatig opgebouwd.","Zodat de last stabiel blijft tijdens het hijsen en niet ongecontroleerd kantelt.","Om de kleur van de tilbanden te selecteren.","Zodat de last sneller geroteerd kan worden.","Ongunstige bevestigingspunten of de ligging van het zwaartepunt kunnen leiden tot kantelen, uitglijden of hellende hellingen."],"a-kantenschutz":["Een hijsband ligt tegen een scherpe onderdeelrand. Wat moet er gedaan worden?","Het onderdeel moet worden opgetild.","Hef de last snel op voordat de band beschadigd raakt.","Gebruik geschikte randbescherming en controleer het type bevestiging.","Maak de laadvloer uitsluitend schoon met een doek.","Scherpe randen kunnen ondersteunende vezels beschadigen; de hijsuitrusting moet dienovereenkomstig worden beschermd."],"a-haken":["Waar let je op bij het bevestigen van een draagdoek?","Je maakt gebruik van een vrachthaak.","Plaats de sling aan de zijkant van de haakpunt.","Houd de veiligheidsklep permanent open.","Laad de haak zoals bedoeld in de haakbasis en let op de veiligheidsvoorzieningen.","Een ontoelaatbare belasting van de punt van de haak en een gebrek aan beveiliging kunnen ertoe leiden dat de haak losraakt."],"a-knoten":["Kun je een te lange hijsband inkorten met een knoop?","De stoplengte past niet.","Nee; Gebruik alleen een geschikt, goedgekeurd type tilband of geschikte tilbanduitrusting.","Ja, als de knoop heel strak wordt aangetrokken.","Ja, zolang de lading momenteel stilstaat.","Knopen kunnen textielstroppen aanzienlijk verzwakken en geïmproviseerde lengteaanpassingen zijn niet toegestaan."],"a-probehub":["Waarom wordt een last in eerste instantie voorzichtig gehesen?","U wilt veilig vervoeren.","Zodat ze zo snel mogelijk kan pendelen.","Om de positie van de tilbanden, stabiliteit en zwaartepunt te controleren.","Omdat het laadvermogen automatisch toeneemt.","Een gecontroleerde eerste slag helpt bij het detecteren van onjuiste stops en onstabiele lastposities."],"a-lastweg":["Waar mogen mensen verblijven terwijl de lading wordt vervoerd?","Met een kraan wordt de lading verplaatst.","Direct onder de last met een veiligheidshelm.","Op de last als ze het vol kunnen houden.","Buiten de gevarenzone en niet onder hangende lasten.","Zelfs bij een zorgvuldige bevestiging bestaat er nog steeds gevaar door vallende of zwaaiende lasten."],"a-haende":["Hoe voorkom je verwondingen tijdens het spenen?","De last nadert het steunvlak.","Houd handen en voeten uit de buurt van het knelgebied en gebruik geschikte hulpmiddelen.","Houd de last met uw blote hand vast.","Ga tussen de last en de muur staan ​​om de positie te corrigeren.","Er ontstaan ​​gevaarlijke knelpunten tussen de last en de steun."],"a-vierstraenge":["Wat geldt voor de lastverdeling bij een vierpootsvering zonder lastcompensatie?","Er is een vaste last bevestigd.","Alle vier de strengen dragen onvermijdelijk hetzelfde bedrag.","Zonder bewijs van uniforme verdeling mag het draagvermogen niet worden gebruikt als algemene schatting voor vier gelijk belaste strengen.","De hellingshoek is dan niet relevant.","Ongelijke strengbelasting is mogelijk bij stijve belastingen; Bij het ontwerp en het toegestane draagvermogen moet hiermee rekening worden gehouden."],"a-chemikalien":["Wat geldt bij gebruik van textieltilbanden die in contact komen met chemicaliën?","U werkt met een onbekende vloeistof.","De kleur van de band toont op betrouwbare wijze de duurzaamheid ervan.","Elke textielband is bestand tegen alle chemicaliën.","Controleer de duurzaamheid en informatie van de fabrikant; Gebruik geen ongeschikte middelen.","Chemicaliën kunnen stroppen aantasten en ongemerkt hun draagvermogen verminderen."],"a-aufbewahrung":["Hoe worden tilbanden na gebruik bewaard?","De missie is voorbij.","Schoon, droog en beschermd tegen beschadiging volgens specificaties van de fabrikant.","Vast op de grond onder een onbeschermde lading.","Aan elke scherpe buitenhaak.","Een juiste opslag voorkomt voortijdige slijtage en maakt visuele inspectie eenvoudiger."],"a-auswahl":["Waar moet u vooral op letten bij gevoelige of scherpe ladingen?","Er moet een geverfd machineonderdeel worden verplaatst.","Alleen de transportsnelheid.","Geschikte stroppen en beschermende maatregelen voor het laadvlak en de randen.","Ongeacht de belasting, altijd dezelfde staalkabel.","Type bevestiging en materiaal moeten overeenkomen met de geometrie, het oppervlak en het gevaar."],"a-abstimmung":["De kraanmachinist heeft geen zicht op u. Hoe geef je instructies?","Je wordt toegewezen als aanvaller.","Je zwaait naar believen totdat er een beweging begint.","Je hoeft maar één keer te bellen en weg te lopen.","Via duidelijk afgesproken borden of andere betrouwbare communicatie.","Aanvallers en kraanmachinisten moeten duidelijk communiceren; Als het onduidelijk is, moet de beweging worden gestopt."],"b-qualifikation":["Wat heeft een persoon nodig om een ​​hydraulische graafmachine tijdens het gebruik veilig te kunnen bedienen?","Een nieuwe persoon moet het werk op de bouwplaats overnemen.","Passende kwalificaties, apparaatgerelateerde instructie en vereiste toewijzing.","Alleen een autorijbewijs.","Even een korte observatie van de operatie.","De werkgever moet zorgen voor de noodzakelijke kwalificaties en de bediener op passende wijze instrueren voor de taak."],"b-pruefung":["Wat is inbegrepen bij de dagelijkse machine-inspectie?","Je neemt een graafmachine over.","Controleer de lakkleur en de stoelbekleding.","Visuele inspectie en functietests volgens de gebruiksaanwijzing, bijvoorbeeld op lekkages en beschadigingen.","Beweeg de giek op volle snelheid totdat deze stopt.","Schade aan de hydraulica, het chassis en de veiligheidsvoorzieningen kunnen tot ernstige ongevallen leiden."],"b-leitungen":["Wat moet er bekend zijn over ondergrondse leidingen voordat er wordt gegraven?","Je zou een greppel moeten graven.","Alleen de geschatte diepte van de geplande bouwput.","De kleur van de bovengrondse markeringen is voldoende.","Verduidelijk de locatie van mogelijke lijnen en bepaal passende beveiligings- en exploratiemaatregelen.","Elektriciteits-, gas- of waterleidingen kunnen bij beschadiging levensbedreigende gevolgen hebben."],"b-schwenkbereich":["Hoe bescherm je mensen in het zwenkbereik van de graafmachine?","Materiaal neem je op met de giek.","Zet de gevarenzone af of beveilig ze en houd personen op afstand.","Beweeg de schep langzaam voordat u gaat draaien.","Rijd over het gebied boven de hoofden.","Draaibare bovenbouw en werkuitrusting creëren beknellings- en stootgevaar."],"b-boeschung":["Wat is belangrijk bij het werken aan de rand van een bouwput?","De graafmachine staat op vaste of gevulde grond.","Alleen al de graafdiepte bepaalt de toegestane plaatsing.","Let op het draagvermogen en de beveiliging van de rand, evenals op de vereiste afstanden volgens de risicobeoordeling.","Rijd zo dicht mogelijk bij de rand om bereik te besparen.","Als er onvoldoende vrije ruimte of een stabiele ondergrond is, kan de ophoging bezwijken en kan de machine vallen."],"b-standsicherheit":["Waarom zijn helling en grond cruciaal voor gebruik?","De bouwplaats ligt op een helling.","De machine is op elke ondergrond even stabiel.","Rupsonderstellen elimineren elk risico op kantelen.","Oneffenheden en hellingen kunnen de stabiliteit beïnvloeden; Toepassingslimieten in acht nemen.","De stabiliteit en kantelveiligheid zijn afhankelijk van de vloer, uitrusting, lading en machinepositie."],"b-wechselgeraet":["Wat controleer je na het verwisselen van een graafbak met behulp van een snelwissel?","Er is een nieuw opzetstuk geïnstalleerd.","Of deze correct is vergrendeld en beveiligd volgens de bedieningsinstructies.","Het is maar of de kleur van de schep overeenkomt.","Of de hydrauliek zo stil mogelijk werkt.","Defecte sloten kunnen ertoe leiden dat opzetstukken vallen."],"b-heben":["Waar moet je op letten bij het hijsen van een vrijhangende last met een graafmachine?","De graafmachine wordt gebruikt voor hijswerkzaamheden.","Alleen de gebruikelijke graafkracht is doorslaggevend.","Let op de toegestane hijslast, geschikte bevestigingspunten en voorgeschreven beschermingsmiddelen.","De last kan aan de tanden van de bak worden gehaakt.","Het hijsen is alleen binnen de beoogde bedrijfsomstandigheden met geschikt materieel toegestaan."],"b-rueckwaerts":["Je moet achteruit rijden, maar je ziet het pad niet. Wat is juist?","Andere werknemers zijn in de buurt.","Rijd voorzichtig weg zonder zicht.","Gewoon toeteren en blijven rijden.","Stop, zorg voor zicht en de gevarenzone of zorg voor passende instructies.","Achteruitrijden mag geen personen in gevaar brengen; beperkte zichtbaarheid vergt aanvullende maatregelen."],"b-kabel":["De giek zou in de buurt van een bovengrondse hoogspanningslijn kunnen komen. Wat ben je aan het doen?","Je werkt op een krappe bouwplaats.","Overleg vooraf met de verantwoordelijken de gevarenzone en passende beschermende maatregelen.","Negeer de lijn als de giek geverfd is.","Beweeg de giek alleen bijzonder snel.","Elektrische gevaren ontstaan ​​door contact en flashover; veilige afstanden en beschermende maatregelen zijn noodzakelijk."],"b-verlassen":["Hoe parkeer je de graafmachine voordat je vertrekt?","Je neemt een pauze.","Laat de giek vrij zweven.","Zet de arbeidsmiddelen veilig neer en beveilig de machine tegen beweging en onbevoegd gebruik.","Laat de motor draaien en de cabine open.","Verlaagde arbeidsmiddelen en bescherming tegen onbedoelde bewegingen verminderen het risico op ongevallen."],"b-hydraulik":["U merkt dat hydraulische olie onder hoge druk op een beschadigde leiding staat. Wat is juist?","Er lekt een leiding.","Voel het lek met uw hand.","Bevestig een nieuwe klem onder druk.","Zet de machine veilig stil, laat de druk afbouwen en laat reparaties uitvoeren door geautoriseerd vakpersoneel.","Hydraulische vloeistof onder hoge druk kan ernstig letsel veroorzaken; Controleer nooit met de hand op lekken."],"b-unterbau":["Wat is het gevaar van rijden op een onstabiele ondergrond?","De grond is zacht na regen.","De machine kan zinken, glijden of kantelen.","De aandrijving wordt automatisch breder.","Dit maakt het zwenkbereik veiliger.","Onvoldoende laadvermogen kan de stabiliteit en de rijveiligheid aanzienlijk beïnvloeden."],"b-arbeitsgeraet":["Kan iemand onder een opgeheven werktuig werken?","Een mens wil iets onder de schop hebben.","Ja, als de motor stationair draait.","Nee, niet zonder de benodigde veilige ondersteuning en borging van het arbeidsmiddel.","Ja, als de persoon een veiligheidshelm draagt.","Hydraulische apparatuur kan zinken; Onderhoudswerkzaamheden vereisen veilige arbeidsmiddelen."],"b-geraeteart":["Je schakelt over van een hydraulische graafmachine naar een wiellader. Wat is vereist?","Bedienings- en bewegingsgedrag zijn verschillend.","Gewoon hetzelfde schoeisel.","Een proefrit zonder instructies.","De kwalificatie of instructie die vereist is voor het nieuwe machinetype.","De kwalificatie moet overeenkomen met het gebruikte type machine en de specifieke operationele vereisten."],"g-neigung":["Je rijdt met een beladen vorkheftruck op een helling. Wat is belangrijk?","De route heeft een duidelijk stijgingspercentage.","Leid de last altijd bergafwaarts, ook als deze zwaar is.","Leid de lading bergopwaarts en neem de operationele richtlijnen voor het rijden op hellingen in acht.","Ongeacht de rijrichting, hef de vork maximaal op.","Op hellingen en afdalingen moet de last altijd bergopwaarts worden vervoerd; Het voertuig en de gebruiksaanwijzing moeten in acht worden genomen."],"g-gabelabsenken":["Waarom moet de vork omlaag staan ​​tijdens het parkeren?","De vorkheftruck staat geparkeerd voor een pauze.","Zodat anderen de vork kunnen gebruiken om naar boven te klimmen.","Zodat de vork vanaf een afstand beter zichtbaar blijft.","Zodat het tillen van de last geen onnodig risico op struikelen of letsel met zich meebrengt.","Verlaagde lastopnamemiddelen verminderen het risico op ongevallen door uitstekende of niet-vastgezette vorken."],"g-fahrerwechsel":["Een collega wil graag de heftruck lenen. Wat moet aanwezig zijn?","De collega heeft alleen mondelinge toestemming van u.","Hij moet over de nodige kwalificaties en een operationeel mandaat beschikken.","Jouw eigen opdracht geldt automatisch ook voor hem.","Voor iedere ondernemer is een rijbewijs voor een personenauto voldoende.","Onafhankelijk leiderschap is gebonden aan persoonlijke geschiktheid, training, kwalificaties en operationele opdracht."],"g-ladungssicherung":["Op een pallet zitten losse, gestapelde dozen. Wat is juist?","Tijdens het rijden kan een kartonnen doos vallen.","Beveilig de lading vóór transport tegen wegglijden en vallen.","Rijd alleen langzaam op bijzonder oneffen terrein.","Compenseer losse dozen met een hogere vorkpositie.","De lading moet stabiel zijn en beveiligd tegen vallen voordat deze met de vrachtwagen wordt vervoerd."],"g-bodenbelastung":["Voor je ligt een deken met een beperkt draagvermogen. Hoe beslis je?","De route voert over een gemiddeld niveau.","Let alleen op het gewicht van de vrachtwagen zonder lading.","Verduidelijk de toegestane vloerbelasting voor vorkheftrucks en lasten.","Rijd met momentum zodat het plafond minder lang belast wordt.","Relevant is de totale werkelijke belasting van het gebied, inclusief voertuig-, lading- en dynamische invloeden."],"g-verkehrswege":["Een gemarkeerd voetpad kruist uw pad. Wat is juist?","Voetgangers kunnen op elk moment de oversteek betreden.","Met de claxon kun je altijd voorrang claimen.","U mag onopgemerkt over de markering rijden.","Pas je snelheid aan, let op voetgangers en rij pas verder als het pad vrij is.","Verkeersroutes moeten worden gereden met aandacht voor mensen; Waarschuwingsborden zijn geen vervanging voor veilig zicht en een duidelijke route."],"g-parkbremse":["Een heftruck parkeer je op een vlakke ondergrond. Wat houdt dat in?","U wilt de bestuurdersstoel enkele minuten verlaten.","Parkeren, parkeerrem aantrekken en beveiligen tegen onbevoegd gebruik.","Laat het voertuig uitsluitend in de neutrale stand staan.","Laat de vork op hoofdhoogte staan, zodat niemand hem aanraakt.","Voordat u vertrekt, moet de vrachtwagen veilig tot stilstand worden gebracht en tegen onbedoelde beweging worden beveiligd."],"g-typenschild":["Welke informatie is bindend als het gaat om de lading op een heftruck?","Je wilt een zware machine oppakken.","Het geschatte laadvermogen op basis van de voertuiggrootte.","Gegevens van de fabrikant in het belasting- of draagvermogendiagram.","Het gewicht van de laatst getransporteerde pallet.","De toegestane last wordt bepaald door de gegevens van de fabrikant en is onder andere afhankelijk van het lastzwaartepunt en de hefhoogte."],"g-tore":["Je nadert een lage doorgang met een vorkheftruck. Wat controleer je?","Er staat een torenhoge lading op het voertuig.","Of doorgang inclusief lading en bevestiging veilig mogelijk is.","Enkel de hoogte van het vorkenbord zonder last.","Of je sneller door kunt rijden voordat de poort sluit.","Vóór doorgangen moet rekening worden gehouden met de vrije hoogte en breedte, evenals met de afmetingen van de lading en het voertuig."],"g-reifen":["Tijdens uw dagelijkse controle constateert u een zwaar beschadigde band. Wat ben je aan het doen?","Veiligheidsrelevante schade is zichtbaar op de band.","U rijdt langzaam tot uw reguliere onderhoudsafspraak.","Je verhoogt de bandenspanning en blijft rijden.","U neemt het voertuig niet in gebruik en meldt de schade.","Beschadigde banden kunnen de stabiliteit en het rijgedrag nadelig beïnvloeden; het defect moet vóór gebruik worden opgehelderd."],"h-absperren":["Medewerkers lopen onder uw werkplatform door. Wat is nodig?","Er bestaat gevaar door vallend gereedschap.","Een geschikte beschermende of beperkte ruimte onder de werkplek.","Even een mededeling als je voor het eerst langskomt.","Bewaar gereedschap zo ver mogelijk van de rand van de mand.","Een werkruimte onder verhoogde werkplekken moet worden beveiligd tegen gevaar door vallende delen."],"h-werkzeuge":["Hoe vervoer je gereedschap in de werkmand?","Op hoogte zijn meerdere kleine gereedschappen nodig.","Plaats ze losjes op de reling, zodat ze binnen handbereik zijn.","Op een zodanige wijze opslaan en beveiligen dat ze niet kunnen vallen of de werking belemmeren.","Bevestig aan de buitenkant van de reling in uw zak.","Losse voorwerpen kunnen vallen en mensen in gevaar brengen; veilige opslag is vereist."],"h-abstuetzung":["Op een putdeksel staat een steun. Wat moet er gecontroleerd worden?","Je wilt het platform verhogen.","Zorg ervoor dat het deksel droog is.","Of de last op dat punt veilig kan worden opgenomen.","Of de overige steunen niet gebruikt hoeven te worden.","De ondergrond en contactvlakken moeten de steunkrachten veilig kunnen opvangen; Dekkingen dienen apart beoordeeld te worden."],"h-notaus":["Wanneer moet het noodstopapparaat worden gebruikt?","Er vindt onmiddellijk een gevaarlijke beweging plaats.","Alleen aan het einde van een reguliere dienst.","Voor het stoppen bij acuut gevaar volgens de gebruiksaanwijzing.","Ter vervanging van de geplande verlaging.","De noodstop wordt gebruikt om gevaar af te wenden, niet de gebruikelijke controle of normale uitschakeling."],"h-schraegstellung":["De waarschuwing voor het kantelen van het podium reageert. Hoe reageer je?","De machine staat op een hellend oppervlak.","Bij lage werkhoogte negeer je de waarschuwing.","Ondanks de waarschuwing rijd je naar de hoogste hefpositie.","Je stopt en brengt het podium in een veilige toestand volgens de instructies van de fabrikant.","Kantelwaarschuwingen kunnen duiden op onvoldoende stabiliteit; verdere bewegingen mogen het gevaar niet vergroten."],"h-umgebung":["Wat moet er geregeld worden bij vestiging in de buurt van een verkeersgebied?","Voertuigen kunnen het podium raken.","Bescherming tegen botsingen en passende verkeersbegeleiding.","Zwaai de werkbak zo ver mogelijk over de weg.","Gewoon een waarschuwingsoproep voordat u opstart.","Hoogwerkers moeten beschermd zijn tegen botsingen met weggebruikers; de installatie moet dienovereenkomstig worden beveiligd."],"h-ueberlast":["De overbelastingswaarschuwing in de mand wordt geactiveerd. Wat ben je aan het doen?","Er werden aanvullende hulpmiddelen uitgenodigd.","Voltooi het werk met een hogere snelheid.","Stel de toegestane korfbelasting vast en volg de instructies van de fabrikant.","Schakel het waarschuwingssignaal permanent uit.","De maximaal toegestane belasting van de mand, inclusief personen en materiaal, mag niet worden overschreden."],"h-quetschen":["Je rijdt de mand dicht onder een afdak. Welk gevaar is bijzonder belangrijk?","Er is weinig ruimte over boven de mand.","Klemmen of pletten tussen de mand en de structuur.","Dat de motor meer brandstof verbruikt.","Dat de rijrichting altijd automatisch omkeert.","Kleine ruimtes boven of naast de werkbak kunnen ernstige verwondingen veroorzaken."],"h-stromausfall":["Zonder hoofdaandrijving blijft het podium op grote hoogte. Wat is juist?","De normale mandbediening reageert niet meer.","Je klimt zonder veiligheid langs de giek naar beneden.","Je wacht tot het einde van je dienst zonder dat je hiervan op de hoogte wordt gesteld.","Start de voorbereide reddingsactie met getrainde mensen en een nooddaling.","Bij verstoringen moet een veilige redding worden gepland; Getrainde mensen moeten de noodfuncties kennen."],"h-transportstellung":["Hoe bereid je een transport voor?","De hoogwerker wordt op een geschikt voertuig geladen.","Breng de giek en het platform in transportpositie volgens de bedieningsinstructies.","Zet het platform zo ver mogelijk vast.","Laat de steunen uitgeschoven zodat deze meer ruimte in beslag nemen.","De voorgeschreven transportpositie en ladingzekering zijn gebaseerd op de fabrikant- en transportspecificaties."],"k-bremsprobe":["Wat blijkt uit een functionele test van de kraanrem vóór gebruik?","Je wilt een lading veilig kunnen vasthouden.","Of de rem stopt en de beweging vasthoudt zoals bedoeld.","Even of de cabineverlichting het doet.","Of de haak automatisch een last kan vasthouden.","Voor gebruik moeten veiligheidsrelevante functies worden gecontroleerd volgens de specificaties."],"k-schraegzug":["Kun je met de kraan een zijwaartse last schuin trekken?","De haak bevindt zich niet verticaal boven de last.","Ja, als de kraan nog lastreserve heeft.","Nee, lasten mogen niet met ontoelaatbare diagonale trekbewegingen worden getrokken.","Ja, als de tilbanden bijzonder kort zijn.","Diagonaal trekken kan ongecontroleerde bewegingen en extra belasting van de kraan en de stroppen veroorzaken."],"k-verhakt":["Er hangt een last aan de onderconstructie. Wat is juist?","Er wordt weerstand gevoeld bij het tillen.","Je blijft tillen totdat het wegkomt.","Je beweegt de last schoksgewijs zijwaarts.","U stopt en laat de bevestiging of verstopping veilig verwijderen.","Vastzittende lasten mogen niet met geweld worden losgescheurd, omdat er onaanvaardbare krachten kunnen ontstaan."],"k-anzuheben":["Waar let je op als je een hangende last voor de eerste keer kortstondig optilt?","De last komt enkele centimeters van de grond.","Of hij in balans hangt en de stop veilig is.","Of iemand zichzelf direct onder de last kan plaatsen.","Of de kraan stabieler wordt door snel te draaien.","Kort gecontroleerd heffen wordt gebruikt om de bevestiging, het evenwicht en het veilige lastgedrag te controleren."],"k-lastweg":["Waar moet de transportroute van een kraanlast zijn?","Onder het mogelijke lastpad bevinden zich meerdere werkplekken.","Indien mogelijk boven bezette werkplekken.","Op een gepland, duidelijk pad zonder dat mensen gevaar lopen.","Altijd diagonaal door het drukste gebied.","Ladingsroutes moeten zo worden ingericht dat personen geen gevaar lopen door hangende lasten."],"k-signalverlust":["De radioverbinding met de maarschalk wordt verbroken. Wat ben je aan het doen?","U kunt het laadpad zelf niet zien.","Je zet de beweging langzaam voort.","Je zwaait experimenteel in de vorige richting.","Je stopt de beweging totdat er een duidelijk, veilig begrip is.","Als er een gebrek aan communicatie is, kan het zijn dat de verwarrende lastbeweging niet voortduurt."],"k-haken":["De veiligheidshaak sluit niet betrouwbaar. Wat is juist?","Tijdens de inspectie wordt een defecte sluiting opgemerkt.","De fout moet vóór verder gebruik professioneel worden gecorrigeerd.","Je knoopt de sluiting strak vast met een kabelbinder.","Je gebruikt de haak alleen voor lichte lasten.","Defecte bevestigingsmiddelen aan de lasthaken kunnen ertoe leiden dat de stroppen losraken en moeten worden verholpen."],"k-zugrichtung":["Wat is belangrijk voor de verticale ondersteuning van een last?","De last moet van een machine worden gehesen.","De kraanhaak moet boven het zwaartepunt van de last worden uitgelijnd.","De haak moet zo zijwaarts mogelijk worden geplaatst.","Voordat de last wordt geheven, moet deze worden geduwd.","Een zo verticaal mogelijke krachtwerking boven het lastzwaartepunt vermijdt ontoelaatbare zijdelingse krachten en ongecontroleerd uitzwaaien."],"k-wartung":["Op de kraan wordt een ongebruikelijk knarsend geluid opgemerkt. Hoe ga je ermee om?","Het geluid ontstaat bij het tillen.","Verberg het geluid door een hogere snelheid.","Stop de activiteiten veilig, meld defecten en laat ze ophelderen.","Werk zonder voorafgaande kennisgeving door tot de pauze.","Merkbare veranderingen kunnen op veiligheidsrelevante schade duiden en een inspectie vereisen."],"k-absetzen":["Wat moet gegarandeerd worden bij het laten zakken van een kraanlast?","Op een oppervlak wordt een zware last geplaatst.","De lading mag onbeveiligd op een hellend vlak liggen.","De stroppen worden verwijderd terwijl het nog drijft.","De lading is stabiel en beveiligd tegen kantelen of wegrollen.","Pas nadat de last veilig is neergezet en de stabiliteit is vastgesteld, mag de last van het hijswerktuig worden losgelaten."],"l-schwerpunkt":["Waarom moet het zwaartepunt bekend zijn voordat er wordt toegeslagen?","Er moet een asymmetrisch gevormde machine worden getransporteerd.","Zodat de last bij het tillen zo goed mogelijk in balans blijft.","Zodat de hijsbanden zo lang als gewenst kunnen worden gekozen.","Zodat het toegestane draagvermogen geen rol speelt.","De positie van het zwaartepunt beïnvloedt de lastverdeling en het veilige evenwicht bij het heffen."],"l-etikett":["Een hijsband heeft geen leesbaar draagvermogenlabel. Wat is juist?","De markering is onherkenbaar geworden.","Schat het draagvermogen in op basis van de kleur.","Gebruik de hijsband niet voordat de geschiktheid ervan duidelijk is aangetoond.","Gebruik de riem slechts één keer voor kleine ladingen.","Voor stroppen zijn geschikte markeringen vereist; Onverklaarbare draagkracht sluit een veilige selectie uit."],"l-kantenschutz":["Over een scherpe stalen rand ligt een textielband. Wat is nodig?","De lading heeft scherpe randen.","Trek de band zo strak mogelijk aan zonder bescherming.","Voer de slag sneller uit.","Gebruik geschikte randbescherming of ander geschikt hijsmateriaal.","Scherpe randen kunnen textielstroppen beschadigen of snijden; passende bescherming is vereist."],"l-spreizwinkel":["Welke invloed heeft een grotere hellingshoek op de belasting van stroppen?","Met behulp van twee schuine touwen wordt een last gehesen.","Bij minder gunstige hoeken kunnen de krachten in de strengen toenemen.","De strengkrachten verdwijnen.","De hoek heeft geen invloed op de spanning.","Bij een minder gunstige aanslaghoek kunnen de krachten per streng toenemen; Tabellen met draagvermogens moeten in acht worden genomen."],"l-knoten":["Kan een tilband naar wens worden ingekort met een knoop?","Het touw is te lang voor de geplande belasting.","Ja, een strakke knoop verbetert het draagvermogen.","Nee, gebruik alleen goedgekeurde inkort- en verankeringsmethoden.","Ja, als de knoop met tape is vastgezet.","Ontoelaatbare knopen verzwakken stroppen en veranderen hun toegestane draagvermogen."],"l-zeichen":["Wat geldt voor de communicatie met de persoon die de kraan bedient?","Het laadpad is gedeeltelijk verborgen.","Meerdere mensen geven tegelijkertijd verschillende signalen.","Er wordt gebruik gemaakt van duidelijke, vooraf afgesproken signalen.","Communicatie is nooit vereist met radiokranen.","Duidelijke borden en duidelijke verantwoordelijkheden voorkomen gevaarlijke foutieve bewegingen."],"l-sichtpruefung":["Wanneer moeten tilbanden op zichtbare gebreken worden gecontroleerd?","U wilt een tilband gebruiken.","Let voor gebruik op eventuele uiterlijk zichtbare schade.","Alleen als er al een ongeluk is gebeurd.","Slechts één keer bij eerste aankoop.","Vóór elk gebruik moet de veilige werkomstandigheden worden beoordeeld; Zichtbare schade staat een veilig gebruik in de weg."],"l-drehung":["Een geheven last begint ongecontroleerd te draaien. Wat ben je aan het doen?","De last beweegt in het lastpad.","Je steekt je hand tussen de last en de muur.","Je plaatst jezelf onder de last en houdt je eraan vast.","Je houdt afstand en laat de beweging gecontroleerd stoppen.","Ongecontroleerde lastbewegingen creëren gevaar voor beknelling en stoten; Mensen moeten de gevarenzone verlaten."],"l-ablegen":["Wanneer kunnen stroppen van de last worden verwijderd?","De last wordt op schragen geplaatst.","Als de lading stabiel is en beveiligd tegen kantelen of wegrollen.","Zodra hij voor het eerst de grond raakt, ongeacht zijn positie.","Terwijl je nog steeds zweeft om tijd te besparen.","Tilbanden mogen pas worden verwijderd nadat ze veilig en stabiel zijn neergezet."],"l-ketten":["Een kettingstrop heeft een ernstig verbogen schakel. Wat ben je aan het doen?","De schade is al vóór het hijsen zichtbaar.","Wikkel het beschadigde gebied in met draad.","Stel de ketting buiten gebruik en laat deze professioneel controleren.","Hef de last slechts half zo hoog.","Vervormde kettingschakels zijn zichtbare beschadigingen die een veilig gebruik in de weg kunnen staan."],"b-einweiser":["Wat is belangrijk als het zicht vanaf de graafmachine beperkt is?","Een deel van het gebouw verduistert het rijgebied.","Passende visuele maatregelen of instructie en duidelijke communicatie.","Kijk maar naar de motorkap.","Rijd door het draaigebied ondanks dat het onzichtbaar is.","Als het zicht beperkt is, moeten gevaren worden voorkomen door aanvullende organisatorische en technische maatregelen."],"b-aushub":["Waar kan afgegraven materiaal worden opgeslagen nabij een bouwput?","De rand van de put mag geen extra risico lopen.","Direct op de rand opstapelen, zodat opritten vrij blijven.","Op voldoende veilige afstand en volgens bouwplaatsspecificaties opslaan.","Zonder verder testen op losse schoren plaatsen.","Opgegraven materiaal kan dijken en stutten in gevaar brengen als gevolg van extra belastingen; Er moeten veiligheidsafstanden worden aangehouden."],"b-personen":["Mogen er mensen in het zwenkgebied blijven terwijl de graafmachine rijdt?","Iemand wil meten tijdens het pannen.","Ja, zolang ze een veiligheidshelm draagt.","Ja, als de graafmachine langzaam zwenkt.","Nee, de gevarenzone moet vóór beweging vrij zijn.","Er bestaat gevaar voor ernstig beknellings- en stootletsel in het zwenkbereik; het gebied moet vrijgehouden worden."],"b-ladung":["Hoe vervoer je materiaal veilig met een wiellader?","Een gevulde schop moet over het erf worden gereden.","Met een passende lage transportpositie en een vrij pad.","Met verhoogde schep voor beter zicht.","Met open deuren en sterke stuurhoek.","Een geschikte transportpositie vermindert het risico op kantelen en verbetert de rijstabiliteit."],"b-anbaupruefung":["Wat controleer je na het koppelen van een opzetstuk?","Er werd een nieuwe schep gemonteerd.","Alleen de netheid van het lakwerk.","De veilige vergrendeling en werking volgens de gebruiksaanwijzing.","Het is maar de vraag of het toestel er van buiten hetzelfde uitziet.","Onjuiste vergrendelingen van snelwissels kunnen leiden tot het onbedoeld loslaten van aanbouwdelen."],"b-einstieg":["Hoe stap je veilig in de cabine van de graafmachine?","De treden zijn vies na regen.","Klim via de giek op de cabine.","Stap in één sprong op de rupsen.","Gebruik de aangewezen treden en handgrepen en maak vuile treden schoon.","Geschikte beklimmingen en veilige bevestigingspunten verminderen het risico op uitglijden en vallen."],"b-graben":["Een sleufwand vertoont scheuren en brokkelt af. Wat is juist?","Je werkt vlak naast de sloot.","Stop de werkzaamheden en laat de verantwoordelijken de graafput beveiligen.","Rijd gewoon dichter naar de rand om de sloot af te sluiten.","Verdiep de greppel verder zonder bescherming.","Scheuren en grondbewegingen kunnen duiden op instabiliteit en vereisen een verdere veiligheidsbeoordeling."],"b-betanken":["Waar let je op bij het tanken van een grondverzetmachine?","De tank is bijna leeg.","Zet de motor en de ontstekingsbronnen vast volgens de instructies van de fabrikant en voorkom morsen.","Vul altijd benzine of diesel bij in de cabine.","Rook tijdens het tanken als er geen wind is.","Brand- en milieugevaren bij het omgaan met brandstof vereisen passende beschermende maatregelen."],"b-laufwerk":["Waarom moeten de rupsbanden en het onderstel regelmatig worden gecontroleerd?","U merkt tijdens het rijden ongebruikelijke trillingen op.","Zodat de machine sneller kan bewegen.","Omdat schade de veilige geleiding en stabiliteit kan beïnvloeden.","Want werken mag altijd zonder visuele inspectie.","Schade aan de aandrijving kan de manoeuvreerbaarheid, stabiliteit en veilige werking beïnvloeden."],"b-einweisen":["Wat is er nodig bij het werken in de buurt van openbaar voetgangersverkeer?","Een graafmachine werkt direct aan de rand van een trottoir.","Voetgangers dienen zich zelf door het schommelgebied te bewegen.","Plak gewoon een bordje op de schep.","Zet de gevarenzone effectief af en stuur het verkeer veilig door.","Derden mogen de gevarenzone van grondverzetmachines niet betreden; Passende barrières en verkeersroutering zijn noodzakelijk."],"g2-fahrweg":["Er is vloeistof gemorst op de weg verderop. Hoe ga je ermee om?","De vorkheftruck zou rechtstreeks over het gladde gebied rijden.","Stop met rijden en laat de gevarenplek beveiligen of verwijderen.","Rijd zo snel mogelijk over de plek met opgeheven vork.","Hopen op drogere banden en onveranderd doorrijden.","Vervuilde routes brengen de stabiliteit in gevaar en moeten voldoende worden beveiligd voordat erop wordt gereden."],"g2-sichtladung":["Een hoge pallet blokkeert het zicht vooruit. Wat is juist?","Je moet naar een opslagplaats rijden en kunt de route niet zien.","Til de pallet op totdat u eronder kunt kijken.","Rijd alleen met geschikte, veilige methoden, zoals achteruitrijden met vrij zicht.","Je kunt nog steeds zonder wegwijzer of vrij zicht over de weg rijden.","De rijrichting en het zicht moeten een veilige observatie van de verkeersroute mogelijk maken; Belastingen mogen de visuele inspectie niet vervangen."],"g2-fussgaengerstop":["Een voetganger stopt vlak naast de vorkheftruck. Wat ben je aan het doen?","De persoon bevindt zich binnen het mogelijke rij- en draaibereik.","Haal de voetganger in door kort te accelereren.","Rijd langs de persoon met geheven last.","Stop en rijd alleen verder op veilige afstand.","Mensen moeten uit de gevarenzone blijven; Indien nodig moet de reis worden onderbroken."],"g2-hubmast":["U constateert een beschadigde hydraulische leiding op de hefmast. Wat is van toepassing?","Er lekt zichtbaar hydraulische olie uit het werktuig.","Neem de heftruck buiten gebruik en meld de schade.","Controleer het lek handmatig tijdens het hijsen.","Hef alleen kleinere lasten totdat de dienst voorbij is.","Hydraulische schade kan leiden tot ongecontroleerde bewegingen; veilig gebruik is pas na de test gegarandeerd."],"g2-lagerregal":["U wilt een pallet op een plank opslaan. Wat controleer je eerst?","Het plankniveau is hoog en het draagvermogen moet behouden blijven.","Duw de pallet zo snel mogelijk op het schap.","Controleer of het schapvak, het laadgewicht en de vrije opbergruimte geschikt zijn.","Schat het totale gewicht uitsluitend op basis van het aantal dozen.","Rekken en lastdragers moeten passen bij de last- en opbergsituatie."],"g2-batterieschaden":["Een vorkheftruckaccu is uitwendig beschadigd. Wat is juist?","Vóór het laden worden scheuren of ongebruikelijke vloeistoffen opgemerkt.","Bedek schade met plakband en laad onmiddellijk.","Laat iemand anders de batterij opladen zonder deze te controleren.","Niet opladen of gebruiken en de verantwoordelijke specialisten informeren.","Beschadigde batterijen vormen elektrische en chemische gevaren en vereisen een professionele beoordeling."],"g2-fahrerkabine":["Wat geldt voor losse voorwerpen in de bestuurdersruimte?","Gereedschap ligt op de vloer naast de bedieningspedalen.","Verwijder voorwerpen en houd het bedieningsgebied vrij.","Houd het gereedschap tijdens het rijden slechts met één voet vast.","Verberg losse onderdelen onder de bestuurdersstoel.","Losse voorwerpen kunnen de pedalen blokkeren en de veilige bediening van het voertuig belemmeren."],"g2-uebergabe":["Je neemt een heftruck over na een ploegendienstwisseling. Wat houdt dat in?","Een collega heeft het voertuig voor het laatst gebruikt.","Stel dat de collega alle controles heeft overgenomen.","Voer de noodzakelijke inspectie uit en informeer naar bekende gebreken.","Begin de reis zonder naar de machine te kijken.","Degene die het overneemt, moet ervoor zorgen dat het apparaat vóór gebruik in een veilige toestand verkeert."],"g2-transportsicherung":["Er ligt een hoog voorwerp los op de pallet. Hoe handel je?","Bij het remmen kan de lading naar voren kantelen.","Draag de vork bijzonder hoog, zodat de lading stabiel blijft.","Neem gewoon de bochten langzaam, ga sneller rechtdoor.","Stel de last stabiel op en beveilig deze tegen omvallen of vallen.","Losse ladingen moeten vóór transport worden gestabiliseerd, zodat ze door rem- en rijbewegingen niet kunnen vallen."],"g2-arbeitsende":["Wat is belangrijk bij een onbeheerde vorkheftruck?","Je beëindigt je dienst en verlaat de omgeving.","Parkeer het voertuig veilig en beveilig het tegen wegrollen en onbevoegd gebruik.","Laat de sleutel erin zitten zodat collega’s de machine kunnen vinden.","Laat de vork op ooghoogte staan, zodat deze zichtbaar is.","Veilig parkeren omvat een verlaagde lastbehandeling en bescherming tegen beweging en onbevoegde inbedrijfstelling."],"g2-bremsweg":["Waarom moet u bijzondere aandacht besteden aan de remweg onder belasting?","De vorkheftruck transporteert zware goederen door een magazijngang.","Rem met zware last altijd later dan zonder last.","Pas de snelheid aan het zicht, de grond- en belastingsomstandigheden aan.","Hef tijdens het remmen de last scherp op om beter te vertragen.","Massa en wegconditie beïnvloeden de remweg; aangepaste snelheid is de sleutel."],"g2-rampe":["Wat controleer je voordat je een steile helling beklimt?","Mogelijk is de route te steil voor het voertuig.","Rijd met maximale snelheid op de helling, ongeacht de helling.","Rijd over de rand van de oprit met de last geheven.","Controleer de toegestane helling en veilige bedrijfsmodus uit de voertuigspecificaties.","Er mogen alleen opritten worden gebruikt die binnen de beoogde operationele limieten liggen; Bedieningsinstructies en lastcontrole zijn doorslaggevend."],"g2-zinke":["Een pallet is breder dan de vorkafstand. Waar moet rekening mee worden gehouden?","U bent van plan een ongewoon grote lading op u te nemen.","Pas de vorkafstand en bevestigingspunten aan de lading aan.","Gebruik slechts één tand als de lading te breed is.","Hef de last schuin op tot deze de juiste positie bereikt.","Een gelijkmatige en geschikte lastabsorptie vermindert uitglijden en kantelen."],"g2-betriebsanweisung":["Welke rol speelt de operationele verkeersregulering?","In het magazijn gelden gemarkeerde eenrichtings- en voetgangersgebieden.","Bij heftrucks gelden alleen de regels van de openbare weg.","Volg de aangegeven routes en verkeersregels.","Negeer de markeringen zodra het voertuig is geladen.","Bedrijfsroutes en veiligheidsregels beschermen vorkheftruckverkeer en mensen te voet."],"g2-nothalt":["De besturing reageert ongewoon tijdens het rijden. Wat is juist?","Het voertuig kan niet meer zoals gewoonlijk worden bestuurd.","Rijd met hogere snelheden om de besturing responsiever te maken.","Compenseer de fout bij bijzonder grote stuuruitslagen.","Stop op een veilige plaats en laat het voertuig controleren.","Een slechte besturing brengt de veilige geleiding in gevaar; de machine mag niet ongecontroleerd blijven werken."],"g2-anschlagkette":["U wilt een vrijhangende last verplaatsen met een heftruck. Wat is van toepassing?","Een last moet aan een haak onder de vorken hangen.","Alleen met een goedgekeurd apparaat en geschikte lastopnamemiddelen.","Elke ketting is geschikt als de lading niet zwaar is.","Klem de ketting direct tussen beide vorken.","Vrijhangende lasten veranderen de stabiliteit; Goedkeuringen van de fabrikant en geschikte voorzieningen zijn vereist."],"g2-rollenlast":["Een cilindervormig onderdeel ligt onbeveiligd op een pallet. Wat ben je aan het doen?","Tijdens het transport kan de lading gaan rollen.","Benader de pallet bijzonder schokkerig.","Beveilig het onderdeel tegen wegrollen voordat de pallet wordt opgepakt.","Plaats de tanden zo hoog dat het onderdeel niet zichtbaar is.","Ronde of rollende lasten vereisen een betrouwbare bescherming tegen positieveranderingen."],"g2-pruefplakette":["Hoe weet je of de heftruck inzetbaar is?","Op de machine is een keuringssticker geplakt.","Elke sticker vervangt altijd de dagelijkse visuele inspectie.","Een gebrek aan speling kan worden vervangen door voorzichtig rijden.","Naast de controle van het voertuig moet er ook rekening gehouden worden met de geldige teststatus en operationele goedkeuring.","Terugkerende tests en dagelijkse operationele controles vervullen verschillende veiligheidsfuncties."],"g2-licht":["De verlichting in het magazijn viel plotseling uit. Wat is juist?","Je kunt obstakels op het pad niet meer veilig zien.","Stop met rijden totdat veilig zicht gegarandeerd is.","Verhoog de rijsnelheid om het donkere gebied te verlaten.","Blijf rijden met geheven vorken zonder visuele inspectie.","Een route die niet veilig over het hoofd kan worden gezien, mag niet worden bereden zonder effectieve veiligheidsmaatregelen."],"g2-ueberhang":["Een last reikt ver voorbij de zijkant van de vork. Wat controleer je?","U wilt de pallet door een smalle poort transporteren.","Compenseer de laterale projectie met een snelle curve.","Beoordeel de speling, de stabiliteit en het toegestane draagvermogen voordat u gaat rijden.","Rijd de last op maximale snelheid, ongeacht de vorm ervan.","Overhangen vergroten het risico op botsingen en kunnen de stabiliteit en de benodigde verkeersruimte beïnvloeden."],"g2-wartungsbereich":["Er zijn slagbomen voor een onderhoudsgebied. Hoe gedraag jij je?","Uw gebruikelijke route is tijdelijk gesloten.","Verplaats de slagbomen kort en rij ongemerkt door.","Rijd onder belasting rechtstreeks door het werkgebied.","Houd rekening met de afsluiting en kies een goedgekeurde alternatieve route.","Afgezette gebieden mogen niet zonder toestemming worden betreden of doorreden."],"g2-bremsprobe":["Wanneer heeft een functionele test van de bedrijfsrem zin?","Je maakt de heftruck gereed voor het werk.","Als onderdeel van de vereiste inspectie vóór gebruik.","Alleen uitvoeren na een ernstig ongeval.","Alleen als de vrachtwagen al een hoge snelheid heeft bereikt.","De functionaliteit van veiligheidsrelevante voorzieningen wordt vóór gebruik gecontroleerd."],"g2-fahrzeuganhaenger":["U wilt een aanhangwagen trekken met een heftruck. Wat is vereist?","Het bedrijf plant transport met aangehechte lading.","Bind elke aanhanger aan een vork zonder te controleren.","Goedkeuring van de fabrikant, geschikte koppeling en toegestane trekbelasting in acht nemen.","Verhoog gewoon de bandenspanning en rijd weg.","Treinbedrijf is alleen veilig mogelijk binnen de technische specificaties en met een passende aansluiting."],"g2-rueckfahrt":["Wat is belangrijk bij het achteruitrijden met de heftruck?","Er is een verwarrende ruimte in het gangpad van het magazijn.","Kijk altijd alleen in de achteruitkijkspiegel, ongeacht de omgeving.","Rijd zonder zicht zolang de claxon één keer is ingedrukt.","Observeer de route en de ruimte van personen veilig en laat hen indien nodig instrueren.","Achteruitrijden vereist helder zicht of effectieve extra veiligheidsmaatregelen."],"g2-lastentnahme":["Je pakt een pallet uit een hoge plank. Wat is juist?","Het palet is mogelijk niet gecentreerd.","Neem de last veilig op en stabiliseer deze voordat u deze laat zakken.","Laat de pallet opzij zwaaien terwijl u hem eruit trekt.","Controleer onder de opgeheven pallet of deze beschadigd is.","Gecontroleerd heffen en dalen voorkomt dat lasten vallen en gevaarlijke bewegingen ontstaan."],"h2-absenkweg":["Waarom moet de ruimte onder een hoogwerker vrij blijven?","De mand wordt neergelaten en er worden materialen onder geplaatst.","Druk materialen naar beneden met de mand.","Houd alleen het voetengedeelte van de bestuurder in de gaten.","Voorkom het risico van beknelling en botsingen bij het neerlaten.","In het neerlaatgebied mogen zich geen personen of obstakels bevinden die bekneld kunnen raken."],"h2-transporthoehe":["Hoe verplaats je een mobiel podium over een lage doorgang?","De speling is kleiner dan bij de uitgeschoven giek.","Plaats het platform in een geschikte transportpositie volgens de bedieningsinstructies.","Laat de giek uitgeschoven en beweeg onder het plafond door.","Druk de mand tegen de zijkant van het deurkozijn.","Voor rijbewegingen moeten de totale hoogte en transportpositie overeenkomen met de specificaties van de fabrikant en de doorgang."],"h2-bodenoeffnung":["Naast het podium bevindt zich een onbeveiligde opening in de vloer. Hoe reageer je?","Nabij de opening bevindt zich een aandrijf- of steunpunt.","Plaats een steun direct op de rand van de opening.","Wijzig de montageplaats of laat het draagvermogen en de zekering professioneel controleren.","Dek het gevarenpunt uitsluitend af met een kartonnen doos.","Openingen en randgebieden kunnen bezwijken onder steunbelastingen en er moet effectief rekening mee worden gehouden."],"h2-rettungsperson":["Waarom moet een tweede persoon bekend zijn met de reddingsprocedure?","Een operator zou aan de top arbeidsongeschikt kunnen raken.","Zodat het werk in de mand over het algemeen zonder beveiliging kan plaatsvinden.","Zodat het podium sneller bediend kan worden dan toegestaan.","Zodat in geval van nood een veilige redding kan worden gestart.","Een reddingsconcept moet rekening houden met hulp op de grond bij een storing of noodsituatie."],"h2-werkzeugabwurf":["Wat geldt voor gereedschap op grote hoogte?","Een los stuk gereedschap zou over de rand van de mand kunnen vallen.","Zet gereedschappen vast zodat ze niemand in gevaar brengen of naar beneden vallen.","Plaats eenvoudig gereedschap op de reling om de belasting te verminderen.","Gooi indien nodig gereedschap uit de mand.","Vallende voorwerpen brengen mensen beneden in gevaar; Materiaal moet veilig worden opgeslagen."],"h2-trittstufe":["Een bak moet dienen als extra staruimte in de mand. Wat is juist?","Anders bereik je nauwelijks de werkplek.","Plaats de doos op de reling en klim erop.","Klim niet op geïmproviseerde verhogingen; Gebruik geschikte arbeidsmiddelen.","Laad de mand opzettelijk boven de toegestane hoogte.","Geïmproviseerde verhogingen belemmeren de beoogde valbeveiliging en zijn niet toegestaan."],"h2-lastverteilen":["Waar let je op als er meerdere mensen in de werkmand zitten?","In de mand werken twee mensen met zwaar gereedschap.","Beoordeel de belasting uitsluitend op basis van de gereedschapsgrootte.","Bewaar zwaar gereedschap direct op de beschermrail.","Overschrijd de toegestane korfbelasting, inclusief mensen en gereedschap, niet.","Het toegestane laadvermogen omvat alle personen, materialen en gereedschappen in de mand."],"h2-abstuetzplatte":["Wanneer worden extra vulplaten voor steunen overwogen?","De installatievloer kan slechts een beperkte belasting dragen.","Als dit nodig is voor een veilige lastverdeling volgens specificaties.","Om de steunen zo dicht mogelijk bij de rand van een bouwput te plaatsen.","Om een ​​groter bereik te gebruiken zonder informatie van de fabrikant.","Voor veilige steunkrachten zijn voldoende contactvlakken nodig."],"h2-baugrube":["Een podium dient direct aan de rand van een bouwput te worden geplaatst. Wat controleer je?","Door de bouwput kan de ondergrond zijdelings bezwijken.","Verleng de steunen in de graafput.","Zorg voor voldoende veiligheidsafstand en draagvermogen van de ondergrond.","Compenseer het risico alleen door de mand langzaam op te tillen.","Graafputten kunnen de stabiliteit beïnvloeden als gevolg van hellingen en falen van de ondergrond."],"h2-witterung":["Er ontstaat ijsvorming tijdens gebruik. Hoe handel je?","Bedieningsoppervlakken en werkgebied worden glad.","Verhoog het podium om sneeuw en ijs te vermijden.","Negeer de waarschuwingen zolang het platform verlicht is.","Onderbreek het werk en beoordeel de bedrijfsomstandigheden opnieuw volgens de bedieningshandleiding.","Veranderingen in het weer kunnen de aansprakelijkheid, bruikbaarheid en veilige gebruikslimieten veranderen."],"h2-aufbaukontakt":["Een stalen constructie begrenst het mandpad. Wat is belangrijk?","Bij het tillen bestaat er gevaar voor beknelling tussen de mand en de drager.","Plan bewegingen zo dat uw lichaam en mand niet bekneld raken.","Maak de reis sneller zodat de mand sneller voorbij komt.","Duw de constructie met de mand opzij.","Knelpunten tussen het platform en de omgeving vereisen zorgvuldige observatie en gecontroleerde beweging."],"h2-sicherheitsabstand":["Wanneer moet de gevarenzone van een podium worden afgezet?","Onder het terrein loopt een openbaarvervoerroute.","Alleen als er al een voorwerp gevallen is.","Als derden door bewegingen of vallende voorwerpen in gevaar kunnen worden gebracht.","Nooit, want de werkmand voorkomt in principe alle gevaren.","De ruimte onder en naast het podium moet worden beschermd tegen voorzienbare gevaren."],"h2-korbtor":["Wat geldt voor de toegangsdeur van de werkmand?","Je bent al op werkhoogte.","Laat de deur openstaan, zodat u sneller naar buiten kunt.","Bind de deur permanent open met een touw.","Houd de deur gesloten volgens het meegeleverde vergrendelingsmechanisme.","De aanwezige sloten maken deel uit van de beveiligingsmaatregelen tegen het vallen uit de werkbak."],"h2-energieleitung":["Wat geldt er als een bovenleiding niet veilig is uitgeschakeld?","Je werkt met de hoogwerker bij hen in de buurt.","Zorg voor gespecificeerde veiligheidsafstanden en noodzakelijke beschermingsmaatregelen.","Verplaats de basket vlak voor de lijn, zolang deze niet wordt aangeraakt.","Vertrouw op de kunststof banden en werk zonder gaten.","Elektrische overslag is ook mogelijk zonder direct contact; Er zijn veiligheidsafstanden vereist."],"h2-schwanken":["De werkmand begint ongewoon krachtig te zwaaien. Wat is juist?","De beweging wordt niet langer gecontroleerd.","Oncontroleerbaar bijstellen met snelle tegenbewegingen.","Stop de beweging en controleer de oorzaak of bedrijfsomstandigheden.","Voeg extra personen toe aan de mand om deze zwaarder te maken.","Ongebruikelijke trillingen kunnen duiden op ongeschikte bedrijfsomstandigheden of een storing."],"h2-ladegeraet":["Een laadkabel voor de elektrisch bediende trap is beschadigd. Wat ben je aan het doen?","Bij het aansluiten is beschadigde isolatie zichtbaar.","Raak de schade aan met natte handschoenen.","Druk de stekker zo hard mogelijk in het stopcontact.","Start het laadproces niet en laat de kabel professioneel controleren.","Beschadigde elektrische bedrading vormt een risico op elektrische schokken en brand."],"h2-gelaenderanbau":["Kun je zelf een reling verwijderen om dichterbij te komen?","Een onderdeel verhindert dat mensen de werkplek naderen.","Wijzig of verwijder de beschermingsvoorzieningen niet zelf.","Na het optillen schroeft u de reling los en installeert u deze later.","Werk verder zonder reling, zolang er iemand naast staat.","Structurele beschermingsvoorzieningen mogen zonder toegestane specificaties en veilige vervangingsmaatregelen niet worden gewijzigd."],"h2-lastkran":["Kan het platform gebruikt worden als kraan om een ​​last te heffen?","Materiaal dient vrij hangend naast de werkmand getransporteerd te worden.","Wanneer het gewicht lager is dan uw eigen lichaamsgewicht.","Alleen als de fabrikant en de apparatuur dit speciale gebruik uitdrukkelijk toestaan.","Bevestig eenvoudig een haak aan de reling en til het materiaal op.","Hoogwerkers zijn niet automatisch ontworpen voor kraanwerk of extra hangende lasten."],"h2-arbeitsvorbereitung":["Wat komt er kijken bij de voorbereiding op een nieuwe locatie?","Je kent de bouwplaats nog niet.","Schat gewoon de afstand tot de dichtstbijzijnde parkeerplaats.","Ongeacht de omgeving, breid hem onmiddellijk volledig uit.","Beoordeel de gevaren, bodem, verkeersroutes, reddingsacties en geschiktheid van de uitrusting.","Een locatiegerelateerde risicobeoordeling is een voorwaarde voor veilige bedrijfsomstandigheden."],"h2-kabelschlaufe":["Er ligt een stroomkabel dwars over het podiumpad. Wat is juist?","De kabel kan tijdens de beweging bekneld raken.","Maak de weg vrij en bescherm elektrische kabels tegen beschadiging.","Gebruik de kabel met de wielen als wegdrempel.","Breng de mand omhoog zonder het vloeroppervlak te controleren.","Overreden of beknelde kabels kunnen elektrische en mechanische gevaren veroorzaken."],"h2-leitungsnaehe":["Wie verduidelijkt de beveiligingsmaatregelen op een elektrisch systeem?","Het platform moet dicht bij onder spanning staande apparatuur werken.","De persoon in de mand beslist uitsluitend op het oog.","Betrek de verantwoordelijke autoriteiten erbij en voer gecoördineerde beschermingsmaatregelen uit.","De afstand wordt pas bepaald nadat de werkzaamheden zijn gestart.","Werken in de buurt van elektrische installaties vereist geplande en gecoördineerde beschermingsmaatregelen."],"h2-funkkommunikation":["Waarom moeten signalen tussen de vloer en de mand duidelijk zijn?","Een persoon op de grond helpt bij het manoeuvreren.","Zodat meerdere mensen tegelijkertijd tegenstrijdige instructies kunnen geven.","Zodat de nooddaling zonder instructies kan worden uitgeprobeerd.","Zodat bewegingen pas worden uitgevoerd na duidelijke communicatie.","Duidelijke communicatie vermindert foutieve bewegingen en botsingen tijdens het manoeuvreren."],"h2-neuebedienung":["Je schakelt over naar een ander type podium. Wat is vereist?","De bedieningsfuncties verschillen aanzienlijk.","Apparaatspecifieke instructie vóór zelfstandig gebruik.","Gewoon het bedrijfslogo op het apparaat lezen.","Een proefrit waarbij de mand al uitgeschoven is zonder instructies.","Kwalificatie alleen vervangt geen instructie in het specifieke apparaattype."],"h2-steckanschluss":["Wat moet u controleren voordat u een oplader aansluit?","Een elektrische hoogwerker moet opgeladen worden.","Gebruik elk stopcontact, ongeacht de staat en zekering.","Controleer geschikte aansluiting en onbeschadigde kabel volgens de instructies van de fabrikant.","Haal tijdens het opladen regelmatig de stekker uit het stopcontact.","Geschikte en intacte elektrische aansluitingen beschermen tegen elektrische schokken en brand."],"h2-absperrpersonal":["Tijdens hijswerkzaamheden betreedt een persoon het afgezette gebied. Wat ben je aan het doen?","U kunt een persoon direct onder de werkmand zien.","Blijf rijden als de persoon een veiligheidshelm draagt.","Laat een stuk gereedschap in hun richting vallen als waarschuwingssignaal.","Stop gevaarlijke bewegingen en laat het gebied ontruimen.","Een slagboom vervangt de observatie van de gevarenzone tijdens het bedrijf niet."],"k2-arbeitsplanung":["Wat moet er in de werkvoorbereiding vóór een kraanoperatie gebeuren?","Lading, locatie en transportroute zijn nog niet op elkaar afgestemd.","Hef de zwaarste last eerst zonder verdere planning.","Markeer alleen de kortste route op de halvloer.","Geef vooraf duidelijkheid over het draagvermogen, de hijsbanden, het lastpad en de gevarenzone.","Een geplande kraanbeweging vereist een passende lastbehandeling, veilige routes en gecoördineerde beschermingsmaatregelen."],"k2-hakenposition":["Hoe wordt de kraanhaak over de last gepositioneerd voordat hij wordt gehesen?","De bevestigingspunten bevinden zich onder de kraan.","Zo verticaal mogelijk boven het zwaartepunt volgens de aanslag.","Ver naar de zijkant verschoven, zodat de last sneller naar binnen zwaait.","In ieder geval aan de buitenrand van de lading, ongeacht het zwaartepunt.","Verticale krachtuitoefening en geschikte ankerpunten verminderen zijwaartse bewegingen en ongecontroleerde bewegingen."],"k2-hakengabel":["Een lasthaak vertoont een merkbare vervorming. Wat is van toepassing?","De haak lijkt gebogen ten opzichte van zijn gebruikelijke staat.","Buig de vervorming terug bij de volgende belasting.","Stop het kraanbedrijf en laat de haak door een deskundige controleren.","Bevestig alleen lichte lasten en ga door met werken.","Vervorming kan de veiligheid van de haak beïnvloeden; ongeoorloofd verder gebruik is niet toegestaan."],"k2-zugueberlast":["De last is zwaarder dan aanvankelijk werd aangenomen. Wat ben je aan het doen?","Tijdens de voorbereiding ontstaat er nieuwe gewichtsinformatie.","Vervang de veiligheidsreserve door sneller tillen.","Negeer het gewicht van de last door deze op een ander punt te bevestigen.","Bepaal de werkelijke belasting en controleer de belastingslimieten opnieuw.","Veilig heffen vereist betrouwbare lastgegevens en naleving van alle relevante draagvermogens."],"k2-arbeitskorb":["Kan een gewone kraanhaak gemakkelijk mensen vervoeren?","Een persoon wil naar een hoge werkplek gaan.","Nee, voor personenvervoer zijn toegestane bijzondere voorzieningen en maatregelen nodig.","Ja, als de persoon het tiltouw vasthoudt.","Ja, zodra de slag bijzonder langzaam wordt uitgevoerd.","Het vervoer van personen is alleen toegestaan ​​onder speciale voorwaarden die hiervoor zijn voorzien."],"k2-bruecke":["Een brugkraan beweegt zich langs een gedeeld hallenpad. Wat is belangrijk?","Medewerkers blijven onder de transportroute.","Rijd met de lading net boven de hoofden van de medewerkers.","Houd de laadroute en het verkeersgebied effectief vrij en veilig.","Gebruik alleen de waarschuwingshoorn in plaats van verdere maatregelen.","Mensen die gevaar lopen mogen zich niet onder hangende lasten bevinden of zich op hun transportpad bevinden."],"k2-zweitekrane":["Twee kranen werken in een overlappend gebied. Wat is nodig?","Gieken of lasten kunnen met elkaar botsen.","Beide kraanmachinisten werken tegelijkertijd zonder voorafgaande toestemming.","Bewegingen worden opzettelijk versneld om kruispunten te vermijden.","Coördineer de operaties en neem passende maatregelen om wederzijdse bedreigingen te voorkomen.","Overlappende werkgebieden vereisen een gecoördineerde operationele organisatie en passende waarborgen."],"k2-pruefbuch":["Wat is de betekenis van de verplichte terugkerende kraankeuring?","De machine wordt regelmatig ingezet in operaties.","Het vult de operationele controle aan met het voorgeschreven deskundigenonderzoek.","Het vervangt permanent elke visuele inspectie voordat het werk begint.","Dit is alleen nodig na een crash.","Terugkerende inspecties en voortdurende operationele controles hebben verschillende taken."],"k2-absetzflaeche":["Het beoogde plaatsingsgebied is ongelijk. Hoe handel je?","Bij plaatsing kan de last omvallen.","Plaats de last op een hoek en laat deze ongewijzigd hangen.","Zorg voor een geschikte, draagkrachtige en stabiele ondergrond of ondergrond.","Plaats tijdens het dalen één persoon onder de last.","Plaatsingsplaatsen moeten de lading veilig ondersteunen en gevaarlijke kantel- of rolbewegingen voorkomen."],"k2-anfahrbereich":["Voordat de kraan in beweging komt, is er één persoon in het rijgebied. Wat ben je aan het doen?","De route wordt geblokkeerd door een persoon.","Duw de persoon opzij met een korte proefrit.","Rijd weg met alleen de eindschakelaar, zonder visuele inspectie.","Begin pas met bewegen als de gevarenzone vrij en veilig is.","Rij- en zwenkbewegingen mogen geen personen in gevaar brengen."],"k2-schlaffseil":["Waarom mag de hijskabel bij het neerleggen niet ongecontroleerd slap worden?","De last is erop, de haak wordt verder neergelaten.","Zodat het touw en de haken niet klem komen te zitten of ongecontroleerd worden belast.","Zodat de last vervolgens zijdelings door het touw kan worden getrokken.","Zodat de stroppen zichzelf losmaken van de haak.","Ongecontroleerde kabelgeleiding kan leiden tot verstrikkingen en gevaarlijke lastbewegingen."],"k2-pendel":["Een lading die wordt getransporteerd, begint te zwaaien. Wat is juist?","De last beweegt meer zijdelings dan gepland.","Compenseer met snelle tegenbewegingen en volle snelheid.","Verminder bewegingen gecontroleerd en kalmeer het woon-werkverkeer zonder mensen in de gevarenzone.","Houd de zwaaiende last met uw blote handen vast.","Oscillerende belastingen kunnen mensen en faciliteiten beïnvloeden; rustige bewegingen verminderen het risico."],"k2-funkakku":["De radiobesturing van een kraan heeft een zwakke batterij. Wat is van toepassing?","Tijdens het hijsen kan de verbinding breken.","Hef snel een last voordat de besturing uitvalt.","Als de verbinding verloren gaat, verplaatst u de last door aan de strop te trekken.","Zorg vóór gebruik voor een betrouwbare besturingsaansluiting.","Betrouwbare besturing en communicatie zijn voorwaarden voor gecontroleerde kraanbewegingen."],"k2-mehrereanschlaeger":["Twee mensen geven tegelijkertijd verschillende signalen aan de kraanmachinist. Wat is juist?","De tekens spreken elkaar tegen.","Onderbreek beweging en verduidelijk duidelijke verantwoordelijkheid.","Geef de voorkeur aan het teken van de persoon die verder weg is.","Vervolg de beweging naar eigen gevoel.","Kraanmachinisten hebben behoefte aan duidelijke en ondubbelzinnige communicatie, vooral wanneer de laadroutes verwarrend zijn."],"k2-endabschaltung":["Waarom mag een eindschakelaar niet worden misbruikt als normale slagbegrenzing?","Vaak wordt de last tot de maximale hefafstand verplaatst.","Eindschakelaars maken doorgaans sneller heffen mogelijk zonder zicht.","Eindschakelaars zijn veiligheidsvoorzieningen en vervangen de gecontroleerde werking niet.","Ze moeten bij elke slag zo hard mogelijk worden geraakt.","Veiligheidsvoorzieningen dienen ter bescherming tegen gevaren en mogen niet te veel worden gebruikt zoals gepland."],"k2-wetterbeobachtung":["Bij een grote oppervlaktebelasting neemt de wind aanzienlijk toe. Wat is vereist?","Een groot componentoppervlak fungeert als een zeil.","Hef de last altijd hoger zodat de wind minder invloed heeft.","Vervang de tilbanden door dunnere exemplaren.","Beoordeel de wind- en operationele limieten en pas indien nodig het heffen aan.","Wind kan aanzienlijke extra krachten en slingerbewegingen genereren, vooral bij belastingen op grote oppervlakken."],"k2-ortswechsel":["Wat is belangrijk bij het verhuizen van een mobiele kraan naar een nieuwe locatie?","De omstandigheden van de ondergrond en de ondersteuning veranderen.","Controleer de standplaats en ondersteuning voordat u de last weer oppakt.","Pas de instellingen van de vorige locatie toe zonder te controleren.","Laat tijdens het tillen de steun opnieuw afstellen.","Elke installatielocatie kan verschillende grond- en steunbelastingsomstandigheden hebben."],"k2-betriebsbereich":["Een kraan moet aan de overkant van een straat werken. Wat moet er verduidelijkt worden?","Derden zouden in de gevarenzone kunnen komen.","Beveilig de weg alleen met een claxon.","Vereiste lockdowns, stem- en beschermingsmaatregelen voor de hub.","Hef de lading zo snel mogelijk over voertuigen zonder deze vast te zetten.","Veilig verkeersmanagement voorkomt onnodige risico's voor derden door lasten en kraanbewegingen."],"k2-hochheben":["Na de testlift hangt een last duidelijk scheef. Wat is juist?","Blijkbaar is de focus verkeerd ingeschat.","Ga door met tillen zodat de onbalans zichzelf corrigeert.","Laat één persoon de leunlast trekken.","Zet de last veilig neer en controleer nogmaals de bevestiging en het zwaartepunt.","De testlift wordt gebruikt om vóór transport onjuiste bevestigingen en onstabiele lastposities te detecteren."],"k2-schwebelast":["Mag u een geheven last onbeheerd laten hangen?","De dienst eindigt, maar de last hangt nog steeds aan de haak.","Nee, laat de last veilig zakken en zet de kraan goed vast.","Ja, als de kraan vergrendeld is tegen wegrijden.","Ja, zolang er maar een waarschuwingsbord op de grond staat.","Hangende lasten mogen in principe niet onbeheerd achtergelaten worden."],"k2-mitnahme":["Een collega wil meerijden op een kraanlast. Wat is van toepassing?","De lading moet naar een hoger punt worden getransporteerd.","Meerijden is toegestaan ​​als de collega een helm draagt.","Er mogen geen personen worden vervoerd of vastgemaakt aan normale lasten.","Een ritje is altijd toegestaan, zolang de collega bekend is bij de kraanmachinist.","Het vervoeren van mensen met lasten brengt aanzienlijke risico's op vallen en verpletteren met zich mee."],"k2-warnsignal":["Een operationeel waarschuwingssysteem op de kraan faalt. Wat is juist?","Het is niet meer mogelijk om een ​​waarschuwing te geven voordat u wegrijdt.","Negeer het systeem als de motor draait.","Vervang de waarschuwing permanent door op de behuizing te tikken.","Meld een veiligheidsrelevante storing en onderbreek de werkzaamheden volgens de instructies.","Vereiste waarschuwingsapparatuur moet functioneel zijn, zodat mensen tijdig worden beschermd."],"k2-schneekante":["Een mobiele kraan moet op bevroren, oneffen ondergrond worden ondersteund. Wat is van toepassing?","Door het ontdooien kan de grond zijn draagkracht verliezen.","Beoordeel het draagvermogen en de ondersteuningssituatie onder werkelijke omstandigheden.","Bevroren grond heeft altijd draagkracht.","Plaats steunen alleen op kleine stenen.","Temperatuur, luchtvochtigheid en ondergrondstructuur beïnvloeden het draagvermogen van kraanlocaties."],"k2-laufkatze":["Een trolley rijdt richting een obstakel. Hoe handel je?","Er bevindt zich een voorwerp in het rijgebied.","Duw het voorwerp langzaam weg met de last.","Stop de beweging tijdig en laat het obstakel veilig verwijderen.","Rijd met verhoogde snelheid voorbij het obstakel.","Kraanbewegingen moeten zo worden geleid dat er geen botsingen met obstakels ontstaan."],"k2-anschlagaufnahme":["U moet een last oppakken met behulp van een niet-aangewezen oog. Wat is juist?","Het oogje kon uitsluitend bedoeld zijn voor het bevestigen van een deksel.","Elk oog is geschikt voor volledige kraanbelasting.","Belast het oog alleen met twee personen tegelijk.","Controleer vóór gebruik het draagvermogen en de geschiktheid van het ankerpunt.","Niet ieder bestaand oog is een stabiel bevestigingspunt voor kraanlasten."],"l2-seilbruch":["Een staalkabel vertoont verschillende gebroken individuele draden. Wat is juist?","De breekpunten bevinden zich in het gebied van de lastdragende kabels.","Gebruik geen hijsgereedschap meer en laat dit professioneel beoordelen.","Buig de draaduiteinden met uw blote handen naar achteren.","Blijf het touw gebruiken als de last bijzonder licht is.","Draadbreuken kunnen een wegwerpcriterium zijn; Beschadigde touwen moeten professioneel worden beoordeeld."],"l2-schaekel":["Wat is cruciaal bij het gebruik van een beugel?","Een beugel verbindt de strop en de last.","Vervang de bout door een willekeurige spijker.","Controleer op geschikt draagvermogen, onbeschadigde staat en juiste bouten.","Schat het draagvermogen in op basis van de kleur.","Sluitingen moeten de juiste maat hebben, volledig worden gebruikt en in de beoogde laadrichting."],"l2-tragfaehigkeit":["Waar moet je op letten als je meerdere strengen gebruikt?","De strengen lopen onder een hoek met de verticaal.","Tel eenvoudigweg het draagvermogen van elke streng bij elkaar op.","Hang de last alleen aan de lichtste streng.","Houd rekening met het draagvermogen van het gehele type anker en hoek.","De hellingshoek en het effectieve aantal strengen hebben een aanzienlijke invloed op de toelaatbare belasting."],"l2-schweissnaht":["Kan een geïmproviseerd ankerpunt aan een last worden gelast?","Er zijn geen geschikte aangewezen ophaalpunten voor de lading.","Gebruik alleen goed ontworpen en goedgekeurde ankerpunten.","Elke lasnaad is voldoende zonder testen.","Steek een haak door een opening in het plaatmetaal.","Ankerpunten moeten bewezen geschikt zijn voor de krachten die bij het hijsen betrokken zijn."],"l2-einseitig":["Een last is aan één kant aanzienlijk zwaarder. Hoe ga je ermee om?","Het zwaartepunt ligt buiten het geometrische centrum.","Laat alle strengen dezelfde lengte hebben, ongeacht het zwaartepunt.","Bepaal het zwaartepunt en pas de positie dienovereenkomstig aan.","Hef eerst de last op de volledige hefhoogte.","Als het zwaartepunt niet in het midden ligt, kunnen lasten onverwacht kantelen of kunnen afzonderlijke strengen overbelast raken."],"l2-kettenriss":["Wat geldt bij een kettingketting met zichtbare scheuren?","Er zit een scheur in een van de schakels van de ketting.","Markeer de scheur met verf en til deze onveranderd op.","Wikkel de schakel in met draad en hergebruik deze.","Verwijder onmiddellijk de ketting en informeer de verantwoordelijke persoon.","Scheuren in dragende kettingschakels zijn veiligheidsrelevante schades en vereisen buitenbedrijfstelling."],"l2-lastfuehrung":["Hoe vervoer je een grote lading als er kans is op rotatie?","Tijdens het hijsen kan de last zijwaarts zwaaien.","Gebruik geschikte geleidingsapparatuur en houd een veilige afstand aan.","Houd de last tijdens het rijden direct tussen uw handen.","Ga onder de last staan ​​en lijn deze van onderaf uit.","De lastgeleiding mag er niet toe leiden dat handen of lichamen in de gevarenzone terechtkomen."],"l2-schnueren":["Wat is belangrijk bij het bevestigen van de veters?","De strop wordt om een ​​onderdeel geleid.","Ga uit van hetzelfde draagvermogen als elk ander type anker.","Let op de geschiktheid van het type aanbouwapparaat en de toegestane belasting volgens de markering.","Trek het slingermechanisme enigszins naar elkaar toe zonder te controleren.","Het type veterbevestiging kan het toegestane draagvermogen veranderen en moet op de juiste manier worden gebruikt."],"l2-winkelmesser":["Waarom kun je een platte strenghoek niet negeren?","Twee hijslijnen lopen vrijwel horizontaal naar de lading.","Een vlakke hoek maakt de streng automatisch sterker.","De belasting wordt altijd gelijkmatig verdeeld, ongeacht de hoek.","Hoge strengkrachten kunnen het toegestane draagvermogen overschrijden.","Naarmate de hoek met de verticaal groter wordt, nemen de spanningen op de strengen toe."],"l2-heisse-last":["Wat moet u controleren op hete lading?","Een stalen onderdeel heeft onlangs een hittebehandeling ondergaan.","Neem de temperatuurlimieten van de hijsbanden en de juiste keuze in acht.","Elke textielstrop is bestand tegen elke temperatuur.","De etikettering doet er niet toe als het warm is.","Temperatuur kan het toegestane draagvermogen van stroppen beïnvloeden."],"l2-abstand":["Kunt u bij het neerzetten uw vingers onder de last plaatsen?","De lading moet met millimeterprecisie op een oppervlak landen.","Ja, als u werkhandschoenen draagt.","Nee, houd afstand en gebruik passende hulpmiddelen.","Ja, als de kraanbeweging bijzonder langzaam is.","Lichaamsdelen tussen de last en de basis kunnen bekneld raken."],"l2-verbindung":["Een verbindingsschakel van de tilbandketting is niet vergrendeld. Wat is van toepassing?","De sluiting ontbreekt.","Gebruik de grendel zonder slot als niemand kijkt.","Plak het element af met plakband.","Sla niet totdat de sluiting goed vastzit.","Verbindingselementen moeten volledig en overeenkomstig hun ontwerp worden bevestigd."],"l2-lasthaken":["Waar let je op als je aan een kraanhaak hangt?","Er moeten meerdere stroppen in de haak worden geleid.","Zorg voor een veilige pasvorm en geschiktheid van haken en ophanging.","Plaats stroppen op de punt van de haak.","Vervang het haakslot door een kabelbinder.","De kracht moet worden uitgeoefend zoals bedoeld in de daarvoor bestemde gebieden."],"l2-fasern":["Een hijsband vertoont ernstige verruwing en vezelbeschadiging. Wat is juist?","Ondersteunende vezels zijn zichtbaar beschadigd.","Bedek de schade met een nieuwe knoop.","Haal de hijsband los en laat deze door een specialist controleren.","Til de last dan sneller op.","Beschadigde draagvezels kunnen het draagvermogen van een hijsband aanzienlijk verminderen."],"l2-anheben":["Wat geldt direct na de eerste centimeter tillen?","De last komt net van de basis omhoog.","Trek de last zonder controle naar de volledige hoogte.","Controleer onder de last of de stroppen gespannen zijn.","Controleer de positie van de aanslag, het evenwicht en het bewegingsgedrag.","Een gecontroleerde testlift maakt eventuele instabiliteiten zichtbaar vóór verder transport."],"l2-lastgewichte":["Het laadgewicht is onbekend. Wat is juist?","Het onderdeel heeft geen gewichtsmarkering.","Bepaal het belastbare gewicht voordat u stroppen selecteert.","Schat het gewicht op basis van de kleur van de lading.","Gebruik een tilband met dubbele lengte.","Zonder een bekend of betrouwbaar bepaald gewicht kan de geschiktheid van de tilbanden niet met zekerheid worden gecontroleerd."],"l2-lose-teile":["Op de te hijsen last bevinden zich losse gereedschappen. Wat ben je aan het doen?","Gereedschap kan vallen tijdens het tillen.","Houd gereedschap met één hand vast tijdens het rijden.","Verwijder losse voorwerpen of zet ze effectief vast voordat u ze optilt.","Hef de last iets sneller, zodat er niets wegglijdt.","Losse voorwerpen kunnen vallen en mensen in de omgeving in gevaar brengen."],"l2-wind":["Bij harde wind wordt een grote last vastgemaakt. Wat is van toepassing?","Het onderdeel biedt de wind een groot aanvalsoppervlak.","Hef de last zonder rekening te houden met slingerbewegingen.","Extra personen moeten de last direct vasthouden.","Beoordeel de windomstandigheden en hef niet op als de situatie onveilig is.","Windkrachten kunnen de geleiding en stabiliteit van de lading tijdens transport beïnvloeden."],"l2-unterlage":["Waarom zijn geschikte documenten belangrijk bij het spenen?","Een ronde last zou over de grond wegrollen.","Plaats de last stevig neer en beveilig deze indien nodig tegen wegrollen.","Laat de last direct op de stroppen staan.","Duw de documenten pas onder de lading nadat ze zijn neergelegd.","Geschikte steunen voorkomen omvallen en ongewenste bewegingen bij het neerzetten."],"l2-transportweg":["Wat moet er gecoördineerd worden voordat de lading vervoerd wordt?","De last wordt over meerdere werkgebieden verplaatst.","Alleen de verwachte duur van de hub.","Veilig lastpad, communicatie en noodzakelijke barrières.","Eén persoon moet onder de last de weg wijzen.","Het transporteren van ladingen vereist veilige verkeersroutes en een duidelijke coördinatie."],"l2-schutzschlauch":["Waar moet u op letten bij het gebruik van tilbanden met beschermslang?","Tegen een ruwe rand ligt een band.","Elk dun doek vervangt een geschikte randbescherming.","Een beschermslang heft elke toegestane belastingslimiet op.","Selecteer beschermende uitrusting op basis van geschiktheid en toepassingsvereisten.","Beschermingsmiddelen moeten passen bij het materiaal, de rand en de beoogde belasting."],"l2-reinigung":["Een hijsband was verontreinigd met een onbekende chemische stof. Wat is juist?","De tape is niet meer duidelijk te beoordelen.","Stop het gebruik en verduidelijk de compatibiliteit of staat professioneel.","Reinig met een oplosmiddel en ga onmiddellijk verder met tillen.","Negeer de chemische stof terwijl de tape droog is.","Chemicaliën kunnen de sterkte van textielstroppen aantasten."],"l2-aufhaengung":["Wat controleer je op meerdere strengen op de ophangschakel?","Twee strengen worden samen in een suspensie geplaatst.","Een streng kan naar believen in de punt van de haak bewegen.","Alle verbindingselementen moeten geschikt zijn en geplaatst zijn zoals bedoeld.","Voor kleine ladingen kan een ring met een barst worden gebruikt.","Aanslag- en verbindingselementen moeten draagkrachtig en correct geplaatst zijn."],"l2-einweiserrolle":["Wat geldt er als de aanvaller en het kraanmachinist geen zicht hebben?","Een drager blokkeert het zicht op het afleverpunt.","Coördineer door meerdere mensen zonder verantwoordelijkheid te bellen.","Verplaats de last op basis van geluid zonder instructie.","Organiseer duidelijke, veilige communicatie en stop deze als deze onduidelijk is.","Het gebrek aan zichtbaarheid moet worden gecompenseerd door effectieve coördinatie en veilige communicatie."],"l2-ausserbetrieb":["Een beschadigde slinger werd gerepareerd. Wat is nog meer belangrijk?","Het blijft vrij toegankelijk naast kant-en-klare bronnen.","Beveilig tegen verder onbedoeld gebruik en informeer de verantwoordelijke persoon.","Stuur het product ongemerkt terug naar de voorraad.","Gebruik hem alleen opnieuw als u een bijzonder lichte last draagt.","Afgedankte tilbanden moeten vóór verder gebruik op betrouwbare wijze worden beschermd."],"b2-schwenkradius":["Waarom is de zwenkradius aan de achterkant van een graafmachine van cruciaal belang?","De staart beweegt over een beperkt werkgebied.","Derden kunnen gegrepen worden door de zwaaiende bovenbouw.","De zwenkradius heeft geen invloed op mensen naast de machine.","De achterkant beweegt altijd alleen in de rijrichting.","Bij het zwenken ontstaat ook achter de machine een gevarenzone."],"b2-verkehrseinweiser":["Hoe wordt een rijbeweging beveiligd als het zicht beperkt is?","Een graafmachine moet achter een obstakel manoeuvreren.","Rijd zonder de signalen van de seingever te zien.","Organiseer indien nodig passende instructie met duidelijke communicatie.","Beveilig achteruitrijden alleen door één keer te toeteren.","Verwarrende routes vereisen effectieve maatregelen om botsingen en beknelling te voorkomen."],"b2-standplatz":["Wat geldt voor een graafmachine die op een helling staat?","De vloer is schuin en kan glad zijn.","De machine kan op elke helling zo ver uitschuiven als hij wil.","Plaats de graafmachine altijd op een losse laag aarde.","Controleer vóór gebruik de stabiliteit en gebruikslimieten van de machine.","Hellinghelling en ondergrond hebben een grote invloed op de stabiliteit."],"b2-oberleitung":["Waarom moet de afstand van de giek tot hoogspanningsleidingen worden gepland?","Bij het zwenken kan de giek dicht bij de kabel komen.","Elektrische flashover is ook mogelijk zonder direct contact.","Alleen de bak kan elektriciteit geleiden, niet de giek.","Met droge grond is elke afstand automatisch veilig.","Gebruikslimieten en veiligheidsafstanden moeten worden verduidelijkt voordat elektrische systemen worden benaderd."],"b2-fremdperson":["Een voorbijganger betreedt de bouwplaats in het panninggebied. Wat is juist?","De persoon staat plotseling bij de graafbak.","Til de schep op en zwaai deze over de persoon heen.","Stop onmiddellijk met bewegen en laat het gebied ontruimen.","Blijf de persoon gewoon vanuit het zijraam in de gaten houden.","Personen die zich in de gevarenzone bevinden, mogen door werkbewegingen geen gevaar lopen."],"b2-parkstellung":["Hoe wordt een grondverzetmachine na afloop van de werkzaamheden beveiligd?","De graafmachine blijft onbeheerd op de bouwplaats.","Laat de lepel op hoofdhoogte liggen.","Laat de motor onbeheerd draaien.","Zet de arbeidsmiddelen neer, beveilig de machine en voorkom ongeoorloofd gebruik.","Goed parkeren vermindert onbedoelde bewegingen en ongeoorloofde toegang."],"b2-eigenlast":["Waarom zijn uitrustingslimieten cruciaal bij het heffen met een graafmachine?","Er moet een zware last op de giek worden opgenomen.","Anders kunnen de stabiliteit en het toegestane draagvermogen worden overschreden.","Elke machine kan elke last heffen, zolang de bak maar past.","Alleen de lengte van het hijstouw bepaalt het risico.","Informatie over hef- en draagvermogen is afhankelijk van de uitrusting en de toepassingssituatie."],"b2-untergrundhohlraum":["De vloer boven een oude kelder kan hol zijn. Wat ben je aan het doen?","U moet de graafmachine het gebied in rijden.","Steek de plek over met maximaal momentum.","Controleer het draagvermogen en eventuele holtes voordat u verderrijdt.","Plaats eenvoudigweg een zware last op het oppervlak.","Holten kunnen bezwijken onder het gewicht van de machine, waardoor de machine kan crashen."],"b2-feuchtigkeit":["Na zware regenval wordt de dijk zacht. Wat is juist?","Een graafmachine werkt aan de rand van de dijk.","Plaats de machine dichter bij de rand om het bereik te vergroten.","Negeer de wijzigingen tot het einde van de dienst.","Beoordeel de bodem- en stabiliteitsomstandigheden opnieuw.","Het binnendringen van vocht kan het draagvermogen en de stabiliteit van taluds veranderen."],"b2-bodenprobe":["Waarom moeten leidingplannen vóór het graven worden gecontroleerd?","Kabels kunnen onder de geplande graafwerkzaamheden door lopen.","Zodat lijnen kunnen worden geïdentificeerd en passende beveiligingsmaatregelen kunnen worden gepland.","Zodat er sneller gegraven kan worden, onafhankelijk van systemen van derden.","Omdat machines nooit in de buurt van kabels mogen worden gebruikt.","Ondergrondse toevoerleidingen vereisen een betrouwbare locatiebepaling vóór graafwerkzaamheden."],"b2-maschinenzugang":["Wat geldt bij het in- en uitstappen van de grondverzetmachine?","De machine staat op oneffen terrein.","Schuif de hydraulische leiding uit de cabine naar beneden.","Gebruik de aangewezen treden en zorg voor een veilige ondergrond.","Spring op de zwenkarm terwijl de machine draait.","Veilige beklimmingen en geschikte stopplaatsen verminderen het risico op vallen en beknellingen."],"b2-kupplung":["Hoe controleer je een nieuwe graaflaadcombinatie na installatie?","De bak wordt aangesloten via de snelkoppeling.","Beoordeel de lepel alleen visueel vanaf een grotere afstand.","Ga direct onder de opgeheven lepel staan.","Zorg voor een correcte vergrendeling en voorgeschreven controlestappen.","Aanbouwdelen die niet goed zijn vergrendeld, kunnen losraken en personen in gevaar brengen."],"b2-hydraulikwartung":["Waarom mogen hydraulische leidingen niet onder druk worden geopend?","Er moet een slang vervangen worden.","Ontsnappende vloeistof kan door hoge druk ernstig letsel veroorzaken.","De druk voorkomt altijd dat olie ontsnapt.","Een open lijn kunt u veilig met uw handen controleren.","Vloeistof onder hoge druk kan weefsel binnendringen en vereist een veilige drukontlasting."],"b2-fahrweg":["Je moet over een tijdelijke bouwbrug rijden. Wat controleer je?","De brug is alleen ontworpen voor bepaalde belastingen.","Of de kleur van de brug overeenkomt met de machine.","Laadvermogen en geschiktheid voor het gewicht en de afmetingen van de machine.","Alleen of er al een lichte auto op de brug heeft gereden.","Tijdelijke constructies mogen alleen worden gebruikt binnen hun bewezen draagvermogen."],"b2-baggertransport":["Wat is belangrijk bij het transporteren van een graafmachine op een dieplader?","De machine wordt naar de volgende bouwplaats gebracht.","Laat het arbeidsmiddel losjes over de rand uitsteken.","Houd de cabinedeur open tijdens het rijden.","Zet de machine vast volgens transportspecificaties en controleer de laadapparatuur.","Transportsloten en geschikte laadvoorzieningen voorkomen uitglijden en vallen."],"b2-schaufelfuellung":["Waarom mag een wiellader niet snel rijden met de bak hoog geheven?","De lading is zwaar en de grond is oneffen.","Een hoog zwaartepunt kan het risico op kantelen en zichtproblemen vergroten.","Bij hoge snelheden stabiliseert de bak automatisch.","De schephoogte is niet relevant voor de stabiliteit.","Een verhoogd zwaartepunt verslechtert doorgaans de stabiliteit tijdens het rijden en het nemen van bochten."],"b2-fussgaenger":["Hoe gedraag je je als je naast voetgangers manoeuvreert?","De toegang tot de bouwplaats is ook een voetpad.","Gebruik de schop om voetgangers naar de zijkant te leiden.","Voer de rijbeweging alleen uit als het gebied veilig en beheersbaar is.","Gewoon één keer toeteren en langzaam rijden zonder zicht.","Voertuig- en passagiersverkeer moeten effectief gescheiden of veilig gecoördineerd worden."],"b2-ueberlastwarnung":["Bij het heffen meldt de machine overbelasting. Wat ben je aan het doen?","Een geheven last bereikt de toegestane grenzen.","Schakel de waarschuwing uit en blijf deze ongewijzigd verhogen.","Span de last plotseling aan terwijl de machine draait.","Stop gevaarlijke bewegingen en corrigeer de belastingsituatie veilig.","Overbelastingswaarschuwingen duiden op mogelijke grensoverschrijdingen en stabiliteitsrisico's."],"b2-wasserleitung":["Tijdens het graven wordt een onbekende pijp blootgelegd. Wat is van toepassing?","Op de bouwplannen is de lijn niet weergegeven.","Stop met het werk in het getroffen gebied en laat de lijn professioneel identificeren.","Probeer de lijn te verplaatsen met de graafschep.","Ga door met graven direct onder de lijn zonder te controleren.","Onbekende leidingen kunnen elektriciteits-, gas- of watergevaren veroorzaken."],"b2-hangefahrt":["Hoe bestuur je een graafmachine op een steile helling?","De geplande route voert langs een helling.","Rijd over de helling, ongeacht de limieten van de fabrikant.","Houd rekening met de toegestane hellingsgraad en de voorgeschreven rijstijl van de machine.","Zwenk de giek ver naar buiten om het voertuig in evenwicht te brengen.","De toegestane helling is afhankelijk van de machine, de ondergrond en de gegevens van de fabrikant."],"b2-schlechtebeleuchtung":["Bij het werken in een donkere put is het zicht onvoldoende. Wat is juist?","Je kunt nauwelijks mensen en obstakels zien.","Verhoog de graafsnelheid om de handeling snel te voltooien.","Gebruik de verlichting niet terwijl de motor draait.","Stop met werken tot de gevarenzones voldoende zichtbaar zijn.","Voor gecontroleerde machinebewegingen is veilig zicht op rij- en werkgebieden vereist."],"b2-kettenverschleiss":["Bij de dagelijkse controle wordt een beschadigde rupsband opgemerkt. Wat ben je aan het doen?","Een kettingverbinding vertoont duidelijke schade.","Blijf de machine niet ongecontroleerd gebruiken en meld eventuele schade.","Blijf met hoge snelheid rijden, zodat de ketting recht komt te liggen.","Werk alleen op zachte ondergrond verder zonder te controleren.","Schade aan de aandrijving kan de bestuurbaarheid en stabiliteit negatief beïnvloeden."],"b2-ladearbeiten":["Met de graafmachine laad je een vrachtwagen. Wat is belangrijk?","De vrachtwagenchauffeur blijft dicht bij de laadplaats.","Zwaai de bak over de onbeschermde bestuurderscabine.","Voorkom dat personen zich in de gevarenzone bevinden en coördineer processen.","Begin met laden zonder met de chauffeur te communiceren.","Bij het laden bestaat gevaar door vallend materiaal en zwaaiende bewegingen."],"b2-arbeitsunterbrechung":["Je onderbreekt graafwerkzaamheden voor een vergadering. Wat is van toepassing?","De machine moet enkele minuten stilstaan ​​zonder te worden bediend.","Laat de opgeheven schep achter als markering.","Laat de machine onbeheerd achter terwijl de tractieaandrijving is ingeschakeld.","Zet de machine veilig neer en beveilig de machine tegen onbedoeld gebruik.","Zelfs korte onderbrekingen vereisen een veilige machinestatus."],"b2-rollmaterial":["Bij transport met de wiellader kan los materiaal vallen. Wat is juist?","De lader rijdt dicht langs de medewerkers.","Neem de lading veilig op en kies voor een veilige rijstijl met een geschikte shovelpositie.","Breng de schep zo hoog mogelijk omhoog, zodat de omgeving vrij zicht heeft.","Pak de lading op zonder de bakvulling te beperken.","Losse ladingen, hoge bakposities en slecht zicht kunnen mensen en verkeer in gevaar brengen."]};
